// core.js
const Core=(()=>{
 const pad=n=>String(n).padStart(2,'0');
 const date=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
 const parse=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)};
 const add=(s,n)=>{const d=parse(s);d.setDate(d.getDate()+n);return date(d)};
 const days=(a,b)=>Math.round((parse(b)-parse(a))/86400000);
 const month=s=>s.slice(0,7);
 const monthDay=(y,m,day)=>date(new Date(y,m,Math.min(day,new Date(y,m+1,0).getDate()),12));
 function schedule(c,from,to){let out=[];if(c.frequency==='weekly'||c.frequency==='fortnightly'){let step=c.frequency==='weekly'?7:14;let start=add(c.anchor,Math.ceil(days(c.anchor,from)/step)*step);for(let s=start;s<=to;s=add(s,step))out.push(s)}else{let d=parse(from);d.setDate(1);for(;date(d)<=to;d.setMonth(d.getMonth()+1)){let ds=c.frequency==='twice'?[c.day1,c.day2]:[Number(c.anchor.slice(8))];for(let day of ds){let s=monthDay(d.getFullYear(),d.getMonth(),day);if(s>=from&&s<=to)out.push(s)}}}return [...new Set(out)].sort()}
 function cycle(c,today){const a=schedule(c,add(today,-70),add(today,70));return {start:a.filter(s=>s<=today).at(-1),end:a.find(s=>s>today)}}
 const bs=(amount,currency,rate)=>currency==='USD'?amount*rate:amount;
 const sum=(xs,fn)=>xs.reduce((s,x)=>s+fn(x),0);
 const spend=(s,from,to,id)=>sum(s.expenses.filter(e=>e.date>=from&&e.date<to&&(!id||e.budget===id)),e=>bs(e.amount,e.currency,e.rate));
 function bounds(m){let d=parse(m+'-01');d.setMonth(d.getMonth()+1);return {from:m+'-01',to:date(d)}}
 function monthly(s,m){const b=bounds(m);if(s.incomeRules?.length)return sum(s.incomeRules,r=>bs(r.amount*schedule(r,b.from>r.anchor?b.from:r.anchor,add(b.to,-1)).length,r.currency,s.rate))+bs(s.income.extra,s.income.currency,s.rate);let count=schedule(s.income,b.from,add(b.to,-1)).length;return bs(s.income.amount*count+s.income.extra,s.income.currency,s.rate)}
 function prorate(value,from,to){let total=0;for(let d=from;d<to;d=add(d,1)){let dt=parse(d);total+=value/new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate()}return total}
 function available(s,today){const c=cycle(s.income,today);const rate=s.rate;const extra=prorate(bs(s.income.extra,s.income.currency,rate),c.start,c.end);const reserve=prorate(bs(s.income.saving,s.income.currency,rate),c.start,c.end);const spent=spend(s,c.start,add(today,1));const available=bs(s.income.amount,s.income.currency,rate)+extra-reserve-spent;return {...c,extra,reserve,spent,available,remaining:days(today,c.end)}}
 const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&s>='1900-01-01'&&s<='2200-12-31'&&date(parse(s))===s;
 const positive=(n,zero=false)=>typeof n==='number'&&Number.isFinite(n)&&(zero?n>=0:n>0)&&n<=1e12;
 const currency=c=>['BOB','USD'].includes(c);
 function validate(s){if(!s||s.version!==3||!positive(s.rate)||!currency(s.display)||!['light','dark'].includes(s.theme)||!Array.isArray(s.budgets)||!Array.isArray(s.expenses)||s.budgets.length>1000||s.expenses.length>100000)throw Error('Formato de respaldo KAPI 3.0 inválido.');const c=s.income;if(!c||!['monthly','weekly','fortnightly','twice'].includes(c.frequency)||!positive(c.amount,true)||!positive(c.extra,true)||!positive(c.saving,true)||!currency(c.currency)||!validDate(c.anchor)||!Number.isInteger(c.day1)||!Number.isInteger(c.day2)||c.day1<1||c.day1>28||c.day2<1||c.day2>31||c.day1>=c.day2)throw Error('Configuración de ingresos inválida.');const ids=new Set();for(let b of s.budgets){if(!b||typeof b.id!=='string'||ids.has(b.id)||typeof b.name!=='string'||!b.name.trim()||b.name.length>70||typeof b.category!=='string'||!b.category.trim()||b.category.length>70||!positive(b.amount)||!currency(b.currency))throw Error('Presupuesto inválido.');ids.add(b.id)}const es=new Set();for(let e of s.expenses){if(!e||typeof e.id!=='string'||es.has(e.id)||typeof e.name!=='string'||!e.name.trim()||e.name.length>100||!positive(e.amount)||!positive(e.rate)||!currency(e.currency)||!validDate(e.date)||typeof e.category!=='string'||e.category.length>70||(e.budget!==null&&!ids.has(e.budget)))throw Error('Movimiento inválido.');es.add(e.id)}return s}
 return {date,parse,add,days,month,schedule,cycle,bs,sum,spend,bounds,monthly,prorate,available,validate,validDate};
})();

if(typeof module!=="undefined")module.exports=Core;


// planning-core.js
(function(root){
const C=typeof module!=='undefined'?require('./core.js'):Core;
const amount=n=>typeof n==='number'&&Number.isFinite(n)&&n>0&&n<=1e12;
function addMonths(date,months){const d=C.parse(date),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return C.date(d)}
function validate(s){if(!Array.isArray(s.goals)||!Array.isArray(s.incomeRules)||s.goals.length>1000||s.incomeRules.length>100)throw Error('Planificación inválida');const ids=new Set();for(const g of s.goals){if(!g||typeof g.id!=='string'||ids.has(g.id)||typeof g.name!=='string'||!g.name.trim()||g.name.length>70||!amount(g.target)||!['BOB','USD'].includes(g.currency)||!C.validDate(g.created)||!C.validDate(g.due)||g.due<g.created||!Array.isArray(g.contributions)||g.contributions.length>10000)throw Error('Meta inválida');ids.add(g.id);const contributions=new Set();for(const c of g.contributions){if(!c||typeof c.id!=='string'||contributions.has(c.id)||!amount(c.amount)||!C.validDate(c.date))throw Error('Aporte inválido');contributions.add(c.id)}}const rules=new Set();for(const r of s.incomeRules){if(!r||typeof r.id!=='string'||rules.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>70||!amount(r.amount)||!['BOB','USD'].includes(r.currency)||!['monthly','weekly','fortnightly','twice'].includes(r.frequency)||!C.validDate(r.anchor)||typeof r.auto!=='boolean'||!Number.isInteger(r.day1)||!Number.isInteger(r.day2)||r.day1<1||r.day1>28||r.day2<=r.day1||r.day2>31)throw Error('Cobro programado inválido');rules.add(r.id)}return s}
function goalProgress(g,asOf){const saved=C.sum(g.contributions.filter(x=>x.date<=asOf),x=>x.amount),remaining=Math.max(0,g.target-saved),a=C.parse(asOf),b=C.parse(g.due),months=Math.max(1,(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth()+(b.getDate()>a.getDate()?1:0));return {saved,remaining,percent:Math.min(100,Math.round(saved/g.target*100)),monthly:Math.ceil(remaining/months*100)/100,months,overdue:g.due<asOf&&remaining>0}}
function dueReceipts(s,asOf){validate(s);const ids=new Set(s.receipts.map(x=>x.id)),result=[];for(const r of s.incomeRules.filter(x=>x.auto&&x.anchor<=asOf)){const dates=C.schedule(r,r.anchor,asOf);if(dates.length>500)throw Error('Hay más de 500 cobros pendientes en una regla. Ajustá la fecha de inicio antes de automatizarla.');for(const date of dates){const id='income-'+r.id+'-'+date;if(ids.has(id))continue;ids.add(id);result.push({id,name:r.name,amount:r.amount,currency:r.currency,rate:r.currency==='USD'?s.rate:1,date,source:'scheduled',ruleId:r.id})}}return result}
function upcoming(s,asOf){const known=new Set(s.receipts.map(x=>x.id));return s.incomeRules.flatMap(r=>C.schedule(r,r.anchor>asOf?r.anchor:asOf,C.add(asOf,70)).filter(date=>date>=r.anchor&&!known.has('income-'+r.id+'-'+date)).slice(0,1).map(date=>({...r,date}))).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
root.KapiPlanning={addMonths,validate,goalProgress,dueReceipts,upcoming};if(typeof module!=="undefined")module.exports=root.KapiPlanning;
})(typeof window==='undefined'?globalThis:window);


// finance.js
/* Shared pure functions: browser and server. */
(function(root){
const C=typeof module!=="undefined"?require("./core.js"):Core;
const validateBase=C.validate;
function validate(s){validateBase(s);if(!Array.isArray(s.receipts)||s.receipts.length>100000)throw Error('Ingresos inválidos');if(s.generalBudget!=null&&(!Number.isFinite(s.generalBudget.amount)||s.generalBudget.amount<=0||s.generalBudget.amount>1e12||!["BOB","USD"].includes(s.generalBudget.currency)))throw Error("Límite general inválido");const ids=new Set();for(const r of s.receipts){if(!r||typeof r.id!=='string'||ids.has(r.id)||!C.validDate(r.date)||typeof r.name!=='string'||!r.name.trim()||r.name.length>100||!['BOB','USD'].includes(r.currency)||!Number.isFinite(r.amount)||r.amount<=0||r.amount>1e12||!Number.isFinite(r.rate)||r.rate<=0||r.rate>1e12)throw Error('Ingreso inválido');ids.add(r.id)}(typeof module!=="undefined"?require("./planning-core.js"):root.KapiPlanning).validate({...s,goals:s.goals??[],incomeRules:s.incomeRules??[]});return s}
function migrate(s){const copy=JSON.parse(JSON.stringify(s));copy.receipts??=[];copy.goals??=[];copy.incomeRules??=[];return validate(copy)}
function summary(s,month){validate(s);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('Mes inválido');const {from,to}=C.bounds(month),expenses=s.expenses.filter(e=>e.date>=from&&e.date<to),receipts=s.receipts.filter(e=>e.date>=from&&e.date<to),spent=C.spend(s,from,to),received=C.sum(receipts,e=>C.bs(e.amount,e.currency,e.rate));const monthlyLimit=s.generalBudget?C.bs(s.generalBudget.amount,s.generalBudget.currency,s.rate):C.sum(s.budgets,b=>C.bs(b.amount,b.currency,s.rate));return {month,currency:'BOB',spent,received,monthlyLimit,remainingBudget:monthlyLimit-spent,limitSource:s.generalBudget?'general':'categories',netRecorded:received-spent,forecast:C.monthly(s,month),budgets:s.budgets.map(b=>({id:b.id,name:b.name,limit:C.bs(b.amount,b.currency,s.rate),spent:C.spend(s,from,to,b.id),currency:b.currency,amount:b.amount})),expenseCount:expenses.length,receiptCount:receipts.length}}
function parseCSV(text){if(text.length>2000000)throw Error('Máximo 2 MB');text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||cell==='')quoted=!quoted;else throw Error('Comillas inválidas')}else if(!quoted&&(c===','||c==='\n'||c==='\r')){row.push(cell);cell='';if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(Boolean))rows.push(row);row=[]}}else cell+=c}if(quoted)throw Error('Comillas sin cerrar');row.push(cell);if(row.some(Boolean))rows.push(row);if(rows.length>5001)throw Error('Máximo 5000 filas');if(!rows.length)throw Error('CSV vacío');const header=rows.shift().map(x=>x.trim());for(const k of ['fecha','descripcion','monto_original','moneda'])if(!header.includes(k))throw Error('Falta columna '+k);return rows.map((r,i)=>{if(r.length!==header.length)throw Error('Columnas incorrectas en fila '+(i+2));const v=Object.fromEntries(header.map((h,j)=>[h,r[j]]));const amount=Number(v.monto_original),rate=v.moneda==='BOB'?1:Number(v.tipo_cambio_Bs_por_USD);if(!C.validDate(v.fecha)||!v.descripcion.trim()||v.descripcion.length>100||!['BOB','USD'].includes(v.moneda)||!Number.isFinite(amount)||amount<=0||amount>1e12||!Number.isFinite(rate)||rate<=0||rate>1e12)throw Error('Datos inválidos en fila '+(i+2));return {date:v.fecha,name:v.descripcion,amount,currency:v.moneda,rate,category:(v.categoria||'General').slice(0,70),budget:null}})}
function signature(e){return JSON.stringify([e.date,e.name,e.amount,e.currency,e.rate])}
function proposal(s,p){if(!p||p.type!=='set_budget'||typeof p.id!=='string'||!Number.isFinite(p.amount)||p.amount<=0||p.amount>1e12)throw Error('Propuesta inválida');const b=s.budgets.find(b=>b.id===p.id);if(!b)throw Error('Presupuesto inexistente');return {type:'set_budget',id:b.id,name:b.name,amount:Math.round(p.amount*100)/100,currency:b.currency,before:b.amount}}
root.Finance={validate,migrate,summary,parseCSV,signature,proposal};
})(typeof window==='undefined'?globalThis:window);


// app.js

'use strict';
// Amounts retain their original currency and the exchange rate used at entry.
window.KapiCore=Core;
const KEY='kapi.v3';let today=Core.date(new Date());const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function initial(){return {version:3,rate:6.96,display:'BOB',theme:window.KAPI_INITIAL_THEME||'light',income:{frequency:'monthly',amount:0,extra:0,saving:0,currency:'BOB',anchor:today.slice(0,8)+'01',day1:1,day2:15},budgets:[],expenses:[]}}
let state=initial(),storageWarning='',page='home',selectedMonth=today.slice(0,7),undo=null,toastTimer;
try{const saved=localStorage.getItem(KEY);if(saved)state=Core.validate(JSON.parse(saved))}catch(e){storageWarning='No se pudo cargar el guardado anterior. No lo sobrescribiremos sin tu acción. Descargá un respaldo si todavía podés acceder a tus datos en otra pestaña.'}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,c=state.display)=>`${c==='BOB'?'Bs':'USD'} ${new Intl.NumberFormat('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)}`;
const money=bs=>fmt(state.display==='USD'?bs/state.rate:bs);
const short=d=>new Intl.DateTimeFormat('es-BO',{day:'numeric',month:'short'}).format(Core.parse(d));
const titleMonth=m=>new Intl.DateTimeFormat('es-BO',{month:'long',year:'numeric'}).format(Core.parse(m+'-01'));
function notify(s,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=esc(s)+(canUndo?' <button id="undo">Deshacer</button>':'');$('#toast').style.display='block';if(canUndo)$('#undo').onclick=()=>{if(undo){state=undo;undo=null;persist();render();notify('Cambio deshecho.')}};toastTimer=setTimeout(()=>{$('#toast').style.display='none'},canUndo?15000:5500)}
function persist(){try{Core.validate(state);localStorage.setItem(KEY,JSON.stringify(state));storageWarning='';return true}catch(e){storageWarning='Los cambios están en esta pestaña, pero no se pudieron guardar en el navegador. Descargá un respaldo antes de cerrar.';return false}}
function commit(message){let ok=persist();render();notify(ok?message:storageWarning)}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function monthControl(){return `<label class="muted">Mes del informe<input type="month" id="month" value="${selectedMonth}" min="1900-01" max="2200-12"></label>`}
function intro(title,subtitle,extra=''){return `<div class="intro row"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${extra}</div>`}
function totals(){const {from,to}=Core.bounds(selectedMonth);let planned=Core.sum(state.budgets,b=>Core.bs(b.amount,b.currency,state.rate)),spent=Core.spend(state,from,to),income=Core.monthly(state,selectedMonth),saving=Core.bs(state.income.saving,state.income.currency,state.rate);return {planned,spent,income,saving}}
function stats(){const t=totals();return `<div class="cards"><div class="card"><div class="muted">Ingresos previstos del mes</div><div class="stat">${money(t.income)}</div><div class="tag">Según tu calendario de cobros</div></div><div class="card"><div class="muted">Presupuestado al mes</div><div class="stat">${money(t.planned)}</div><div class="tag">Límites de categorías · no son gastos</div></div><div class="card"><div class="muted">Gastos registrados</div><div class="stat">${money(t.spent)}</div><div class="tag">${esc(titleMonth(selectedMonth))}</div></div></div>`}
function budgetCards(){const {from,to}=Core.bounds(selectedMonth);if(!state.budgets.length)return `<div class="card empty">Tu próximo plan empieza acá.<p><button class="primary" data-action="new-budget">+ Crear presupuesto</button></p></div>`;return `<div class="budgets">${state.budgets.map((b,i)=>{let spent=Core.spend(state,from,to,b.id),limit=Core.bs(b.amount,b.currency,state.rate),remaining=limit-spent;return `<article class="card ${remaining<0?'over':''}"><div class="budgettop"><div class="badge">${['◒','↗','✳','◇'][i%4]}</div><div><h3>${esc(b.name)}</h3><div class="tag">${esc(b.category)}</div></div><button class="subtle" data-action="edit-budget" data-id="${esc(b.id)}" aria-label="Editar ${esc(b.name)}">Editar</button></div><div class="tag">Límite mensual · ${b.currency==='BOB'?'Bolivianos':'Dólares'}</div><div class="amount">${fmt(b.amount,b.currency)}</div><div class="meter" role="meter" aria-label="Uso de ${esc(b.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(spent/limit*100))}"><i style="width:${Math.min(100,spent/limit*100)}%"></i></div><div class="row tag"><span>${money(spent)} gastados</span><span class="${remaining<0?'warning':''}">${Math.round(spent/limit*100)}%</span></div><div class="budgetfoot"><span class="tag ${remaining<0?'warning':''}">${money(Math.abs(remaining))}<br>${remaining<0?'por encima':'disponibles'}</span><button data-action="add-budget" data-id="${esc(b.id)}">+ Añadir monto</button></div></article>`}).join('')}</div>`}
function budgetsSection(){return `<div class="sectionhead"><div><h2>Tus presupuestos</h2><p class="muted">Límites mensuales que podés ajustar cuando lo necesités.</p></div><button class="primary" data-action="new-budget">+ Crear presupuesto</button></div>${budgetCards()}`}
function expenseTable(limit){let rows=state.expenses.filter(e=>e.date.slice(0,7)===selectedMonth).sort((a,b)=>b.date.localeCompare(a.date));if(limit)rows=rows.slice(0,limit);return !rows.length?`<div class="card empty">Todavía no hay gastos en este mes.<p>Registrá el primero para empezar a ver tu actividad.</p><button data-action="new-expense">+ Registrar gasto</button></div>`:`<div class="tablewrap"><table><thead><tr><th>Movimiento</th><th>Presupuesto / categoría</th><th>Fecha</th><th class="right">Moneda original</th><th class="right">Equivalente</th><th>Acción</th></tr></thead><tbody>${rows.map(e=>{let b=state.budgets.find(b=>b.id===e.budget);return `<tr><td><strong>${esc(e.name)}</strong><div class="tag">${e.currency==='USD'?`1 USD = Bs ${esc(e.rate)}`:'Registro en bolivianos'}</div></td><td>${esc(b?b.name:e.category)}${b?`<div class="tag">${esc(b.category)}</div>`:''}</td><td>${short(e.date)}</td><td class="right">${fmt(e.amount,e.currency)}</td><td class="right">${money(Core.bs(e.amount,e.currency,e.rate))}</td><td><button class="subtle" data-action="edit-expense" data-id="${esc(e.id)}">Editar</button></td></tr>`}).join('')}</tbody></table></div>`}
function home(){const c=Core.available(state,today);return intro('Tu dinero, con intención.','Un poco de claridad para lo que viene.')+`<section class="hero"><div><div class="eyebrow">Disponible estimado entre cobros</div><div class="big">${money(c.available)}</div><div class="muted">Del ${short(c.start)} al ${short(Core.add(c.end,-1))} · ${money(c.spent)} gastados</div><button data-action="new-expense">+ Registrar gasto</button></div><div class="cycle"><div class="eyebrow">Tu próximo cobro previsto</div><p class="smallstat">${short(c.end)} <span style="font-size:13px;opacity:.7">· en ${c.remaining} días</span></p><div class="muted">${money(Core.bs(state.income.amount,state.income.currency,state.rate))} por pago</div><button data-action="income">Configurar mis ingresos ↗</button></div></section><p class="tag">Estimación con tu sueldo configurado + extras proporcionales − ahorro reservado − gastos del período hasta hoy. No es un saldo bancario; no descuenta compromisos sin registrar.</p><div class="sectionhead"><h2>Este mes, en perspectiva</h2>${monthControl()}</div>${stats()}${budgetsSection()}<div class="sectionhead"><h2>Últimos movimientos</h2><button class="subtle" data-action="all-expenses">Ver todos ↗</button></div>${expenseTable(5)}`}
function reports(){const t=totals(),bounds=Core.bounds(selectedMonth);const by=state.budgets.map(b=>({name:b.name,value:Core.spend(state,bounds.from,bounds.to,b.id)}));by.push({name:'Sin presupuesto',value:Core.sum(state.expenses.filter(e=>!e.budget&&e.date>=bounds.from&&e.date<bounds.to),e=>Core.bs(e.amount,e.currency,e.rate))});let prev=Core.parse(selectedMonth+'-01');prev.setMonth(prev.getMonth()-1);const pb=Core.bounds(Core.date(prev).slice(0,7)),prevSpent=Core.spend(state,pb.from,pb.to);return intro('Una mirada más clara.','Tu actividad resumida, sin perder el detalle.',monthControl())+stats()+`<div class="two"><section class="card"><h2>En qué se fue tu dinero</h2><p class="muted">Gastos por presupuesto · ${esc(titleMonth(selectedMonth))}</p>${t.spent?by.filter(x=>x.value).sort((a,b)=>b.value-a.value).map(x=>`<div class="reportbar"><span>${esc(x.name)}</span><div class="meter"><i style="width:${x.value/t.spent*100}%"></i></div><span class="right">${money(x.value)}<br><small class="muted">${Math.round(x.value/t.spent*100)}%</small></span></div>`).join(''):'<div class="empty">Registrá gastos para ver su distribución.</div>'}</section><section class="card"><h2>Tu plan del mes</h2><p class="muted">${money(t.income-t.planned-t.saving)} sin asignar</p><div class="notice">Ingresos previstos − presupuestos − objetivo de ahorro. ${t.planned+t.saving>t.income?'Tus asignaciones superan el ingreso previsto.':'Podés ajustar tus límites en Presupuestos.'}</div><p>Mes anterior: <strong>${money(prevSpent)}</strong> en gastos.</p><p class="muted">Diferencia: ${money(t.spent-prevSpent)}. Se comparan los registros completos de ambos meses; el mes actual puede estar en curso.</p><button data-action="export-csv">Exportar gastos de este mes ↓</button></section></div><div class="notice">Informe calculado localmente a partir de tus registros. No usa IA ni consulta bancos. Las conversiones de gastos usan el cambio guardado en cada registro; los totales en USD se muestran al cambio actual (${state.rate} Bs/USD).</div>`}
function settings(){let c=state.income;return intro('A tu manera.','Ingresos, monedas y un espacio que se adapta a vos.')+`<div class="settings"><form id="income-form" class="card"><h2>Mis ingresos</h2><div class="fields"><label>Frecuencia de cobro<select name="frequency">${[['monthly','Mensual'],['weekly','Semanal · cada 7 días'],['fortnightly','Cada 14 días'],['twice','Dos veces al mes']].map(([v,l])=>`<option value="${v}" ${c.frequency===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Moneda de mis ingresos<select name="currency">${currencyOptions(c.currency)}</select></label><label>Monto por pago<input name="amount" type="number" min="0" max="1000000000000" step="0.01" value="${c.amount}" required></label><label>Ingresos adicionales mensuales<input name="extra" type="number" min="0" max="1000000000000" step="0.01" value="${c.extra}" required></label><label>Objetivo de ahorro mensual<input name="saving" type="number" min="0" max="1000000000000" step="0.01" value="${c.saving}" required><small class="help">Se reserva proporcionalmente en cada período.</small></label><label id="anchor-label">Fecha de referencia de cobro<input name="anchor" type="date" min="1900-01-01" max="2200-12-31" value="${c.anchor}" required><small class="help">Mensual: repite el día, o el último del mes. Semanal / 14 días: repite desde esta fecha.</small></label><label class="twice-field">Primer día del mes<input name="day1" type="number" min="1" max="28" step="1" value="${c.day1}" required></label><label class="twice-field">Segundo día del mes<input name="day2" type="number" min="2" max="31" step="1" value="${c.day2}" required><small class="help">Si el día no existe, se usa el último día del mes.</small></label></div><div class="notice">Los pagos son previsiones recurrentes, incluso antes de la fecha de referencia. No confirma que recibiste el dinero. Los ingresos adicionales se distribuyen por día del mes para el cálculo entre cobros.</div><div class="error" id="income-error" role="alert"></div><div class="actions"><button class="primary">Guardar ingresos</button></div></form><form id="currency-form" class="card"><h2>Monedas y tipo de cambio</h2><div class="fields"><label>Moneda principal<select name="display">${currencyOptions(state.display)}</select></label><label>1 USD equivale a cuántos Bs<input name="rate" type="number" min="0.000001" max="1000000000000" step="any" value="${state.rate}" required></label></div><div class="notice">${state.rate===6.96?'6,96 es un valor inicial de ejemplo, no una cotización verificada. ':''}El cambio es manual. Modificarlo actualiza presupuestos en USD y visualización de totales; conserva el cambio histórico de cada gasto. Podés editar ese cambio en el movimiento correspondiente.</div><div class="error" id="currency-error" role="alert"></div><div class="actions"><button class="primary">Guardar monedas</button></div></form><section class="card"><h2>Tus datos, bajo tu control</h2><p class="muted">Guardado local en este navegador y en este archivo. No hay cuenta, sincronización entre dispositivos ni envío a servidores.</p><div class="actions" style="justify-content:flex-start"><button data-action="backup">Descargar respaldo JSON</button><button data-action="restore">Restaurar respaldo KAPI 3.0</button></div><p class="tag">El respaldo incluye tu configuración y tus gastos. Mantenelo en un lugar privado. Limpiar los datos del navegador o mover el HTML puede hacer inaccesible el guardado local.</p></section><section class="card"><h2>Banco e inteligencia artificial</h2><p class="muted">Esta versión permite registro manual y respaldos KAPI. No conecta cuentas, no realiza pagos y no importa extractos bancarios CSV, Excel o PDF. El CSV disponible es una exportación de gastos.</p><p class="muted">Los informes son cálculos locales; no hay un modelo de IA conectado. Una integración bancaria o de IA requiere un servicio adicional y autorización específica.</p></section></div>`}
function render(){document.body.classList.toggle('dark',state.theme==='dark');$('#display-currency').value=state.display;$('#theme').setAttribute('aria-label',state.theme==='dark'?'Activar modo claro':'Activar modo oscuro');$('#theme').textContent=state.theme==='dark'?'☀':'◐';$('#today').textContent=new Intl.DateTimeFormat('es-BO',{day:'numeric',month:'long',year:'numeric'}).format(Core.parse(today));document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});let html=page==='home'?home():page==='budgets'?intro('Un plan para cada prioridad.','Creá, ajustá y hacé espacio para lo que importa.',monthControl())+stats()+budgetsSection():page==='expenses'?intro('Cada movimiento cuenta.','Registrá tus gastos en bolivianos o dólares.')+`<div class="sectionhead">${monthControl()}<div class="toolbar"><button data-action="export-csv">Exportar CSV ↓</button><button class="primary" data-action="new-expense">+ Registrar gasto</button></div></div>${expenseTable()}`:page==='reports'?reports():settings();$('#app').innerHTML=(storageWarning?`<div class="notice warning" role="alert">${esc(storageWarning)}</div>`:'')+html;const mc=$('#month');if(mc)mc.onchange=()=>{if(/^\d{4}-\d{2}$/.test(mc.value)){selectedMonth=mc.value;render()}};if(page==='settings')bindSettings()}
function currencyOptions(selected){return `<option value="BOB" ${selected==='BOB'?'selected':''}>Bs · Bolivianos</option><option value="USD" ${selected==='USD'?'selected':''}>USD · Dólares</option>`}
function openModal(title,sub,body,submit,onSubmit,extra=''){const d=$('#modal');d.innerHTML=`<form id="modal-form"><div class="row"><h2 id="modal-title">${title}</h2><button type="button" class="subtle close" aria-label="Cerrar">×</button></div><p class="muted">${sub}</p>${body}<div class="error" id="modal-error" role="alert"></div><div class="actions">${extra}<button type="button" class="cancel">Cancelar</button><button class="primary">${submit}</button></div></form>`;d.querySelector('.close').onclick=()=>d.close();d.querySelector('.cancel').onclick=()=>d.close();$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.target))}catch(err){$('#modal-error').textContent=err.message}};d.showModal()}
function textValue(f,key,max){let s=String(f.get(key)||'').trim();if(!s||s.length>max)throw Error('Completá los campos de texto sin exceder su longitud.');return s}
function numberValue(f,key,zero=false){let raw=f.get(key);let n=Number(raw);if(raw===''||!Number.isFinite(n)||(zero?n<0:n<=0)||n>1e12)throw Error('Ingresá un monto válido'+(zero?' de cero o mayor.':' mayor a cero.'));return n}
function budgetModal(id){let b=state.budgets.find(b=>b.id===id);openModal(b?'Editar presupuesto':'Crear presupuesto','Tu límite mensual se repite cada mes. Cambiarlo no crea un ingreso.',`<div class="fields"><label class="wide">Nombre<input name="name" maxlength="70" value="${esc(b?.name||'')}" placeholder="Ej. Supermercado" required></label><label class="wide">Categoría<input name="category" maxlength="70" value="${esc(b?.category||'')}" placeholder="Ej. Vida diaria" list="categories" required><datalist id="categories">${[...new Set(state.budgets.map(b=>b.category))].map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label><label>Monto mensual<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" value="${b?.amount||''}" required></label><label>Moneda<select name="currency">${currencyOptions(b?.currency||state.display)}</select></label></div>`,b?'Guardar cambios':'Crear presupuesto',f=>{let data={name:textValue(f,'name',70),category:textValue(f,'category',70),amount:numberValue(f,'amount'),currency:f.get('currency')};if(b)Object.assign(b,data);else state.budgets.push({id:uid(),...data});$('#modal').close();commit('Presupuesto guardado. Los ingresos no cambiaron.')},b?'<button type="button" class="danger" id="delete-budget">Eliminar</button>':'');if(b)$('#delete-budget').onclick=()=>confirmDelete('budget',id)}
function addBudget(id){const b=state.budgets.find(b=>b.id===id);if(!b)return;openModal('Añadir monto mensual',esc(b.name)+' · Límite actual: '+fmt(b.amount,b.currency),`<div class="fields"><label class="wide">Cuánto querés añadir (${b.currency==='BOB'?'Bs':'USD'})<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" placeholder="Ej. 300" required autofocus></label></div><div class="notice" id="new-limit">El nuevo límite se aplicará a cada mes. No registra dinero recibido.</div>`,'Añadir al presupuesto',f=>{let n=numberValue(f,'amount');if(b.amount+n>1e12)throw Error('El límite resultante es demasiado alto.');b.amount=Math.round((b.amount+n)*100)/100;$('#modal').close();commit('Nuevo límite mensual: '+fmt(b.amount,b.currency))});$('#modal input').oninput=e=>{let n=Number(e.target.value);$('#new-limit').textContent='Nuevo límite mensual: '+fmt(b.amount+(Number.isFinite(n)?n:0),b.currency)+'. No cambia tus ingresos.'}}
function expenseModal(id){let e=state.expenses.find(e=>e.id===id);openModal(e?'Editar gasto':'Registrar gasto','Conservamos la moneda original y el cambio de este registro.',`<div class="fields"><label class="wide">Descripción<input name="name" maxlength="100" value="${esc(e?.name||'')}" placeholder="Ej. Compra del supermercado" required></label><label>Monto<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" value="${e?.amount||''}" required></label><label>Moneda<select name="currency" id="expense-currency">${currencyOptions(e?.currency||state.display)}</select></label><label>Fecha<input name="date" type="date" min="1900-01-01" max="${today}" value="${e?.date||today}" required></label><label>Presupuesto<select name="budget" id="expense-budget"><option value="">Sin presupuesto</option>${state.budgets.map(b=>`<option value="${esc(b.id)}" ${e?.budget===b.id?'selected':''}>${esc(b.name)} (${b.currency==='BOB'?'Bs':'USD'})</option>`).join('')}</select></label><label class="wide" id="free-category">Categoría del gasto sin presupuesto<input name="category" maxlength="70" value="${esc(e?.category||'General')}" required></label><label class="wide" id="expense-rate-label">Tipo de cambio de este gasto · 1 USD = Bs<input name="rate" type="number" min="0.000001" max="1000000000000" step="any" value="${e?.rate||state.rate}" required><small class="help">Se guarda con el movimiento. No depende del cambio que configures después.</small></label></div>`,'Guardar gasto',f=>{let currency=f.get('currency'),date=f.get('date'),budget=f.get('budget')||null;if(!Core.validDate(date)||date>today)throw Error('Usá una fecha válida hasta hoy.');let b=state.budgets.find(b=>b.id===budget),data={name:textValue(f,'name',100),amount:numberValue(f,'amount'),currency,date,budget,category:b?b.category:textValue(f,'category',70),rate:currency==='USD'?numberValue(f,'rate'):1};if(e)Object.assign(e,data);else state.expenses.push({id:uid(),...data});selectedMonth=date.slice(0,7);$('#modal').close();commit('Gasto guardado con su moneda original.')},e?'<button type="button" class="danger" id="delete-expense">Eliminar</button>':'');function fields(){$('#expense-rate-label').hidden=$('#expense-currency').value!=='USD';$('#expense-rate-label input').disabled=$('#expense-currency').value!=='USD';$('#free-category').hidden=!!$('#expense-budget').value;$('#free-category input').disabled=!!$('#expense-budget').value}$('#expense-currency').onchange=fields;$('#expense-budget').onchange=fields;fields();if(e)$('#delete-expense').onclick=()=>confirmDelete('expense',id)}
function confirmDelete(type,id){const isB=type==='budget';openModal(isB?'Eliminar presupuesto':'Eliminar gasto',isB?'Los gastos se conservarán sin presupuesto y mantendrán su categoría.':'Este movimiento dejará de contar en los informes.','<div class="notice">Podés deshacer esta acción durante 15 segundos.</div>','Eliminar',()=>{undo=JSON.parse(JSON.stringify(state));if(isB){let b=state.budgets.find(b=>b.id===id);state.expenses.forEach(e=>{if(e.budget===id){e.budget=null;e.category=b.category}});state.budgets=state.budgets.filter(b=>b.id!==id)}else state.expenses=state.expenses.filter(e=>e.id!==id);$('#modal').close();persist();render();notify(isB?'Presupuesto eliminado; gastos conservados.':'Gasto eliminado.',true)})}
function bindSettings(){const form=$('#income-form');const toggle=()=>{const twice=form.elements.frequency.value==='twice';document.querySelectorAll('.twice-field').forEach(e=>{e.hidden=!twice;e.querySelector('input').disabled=!twice});$('#anchor-label').hidden=twice;form.elements.anchor.disabled=twice};form.elements.frequency.onchange=toggle;toggle();form.onsubmit=ev=>{ev.preventDefault();try{let f=new FormData(form),c=state.income,twice=f.get('frequency')==='twice',day1=twice?numberValue(f,'day1'):c.day1,day2=twice?numberValue(f,'day2'):c.day2,anchor=twice?c.anchor:f.get('anchor');if(twice&&(!Number.isInteger(day1)||!Number.isInteger(day2)||day1<1||day1>28||day2>31||day2<=day1))throw Error('El segundo día debe ser posterior al primero.');if(!Core.validDate(anchor))throw Error('Ingresá una fecha de referencia válida.');state.income={frequency:f.get('frequency'),currency:f.get('currency'),amount:numberValue(f,'amount',true),extra:numberValue(f,'extra',true),saving:numberValue(f,'saving',true),anchor,day1,day2};commit('Ingresos y calendario actualizados.')}catch(e){$('#income-error').textContent=e.message}};$('#currency-form').onsubmit=ev=>{ev.preventDefault();try{let f=new FormData(ev.target),r=numberValue(f,'rate');state.rate=r;state.display=f.get('display');commit('Monedas actualizadas. Se conservaron los cambios históricos.')}catch(e){$('#currency-error').textContent=e.message}}}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function backup(){download('KAPI_respaldo_'+today+'.json',JSON.stringify(state,null,2),'application/json');notify('Respaldo preparado. Revisá tus descargas.')}
function exportCSV(){const rows=[['fecha','descripcion','presupuesto','categoria','monto_original','moneda','tipo_cambio_Bs_por_USD','equivalente_Bs'],...state.expenses.filter(e=>e.date.slice(0,7)===selectedMonth).map(e=>[e.date,e.name,state.budgets.find(b=>b.id===e.budget)?.name||'',e.category,e.amount,e.currency,e.rate,Core.bs(e.amount,e.currency,e.rate).toFixed(2)])];const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'"+'$&').replace(/"/g,'""')+'"';download('KAPI_gastos_'+selectedMonth+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');notify('CSV del mes preparado.')}
function restore(){let incoming;openModal('Restaurar respaldo KAPI 3.0','Reemplaza los datos de esta pestaña. Primero descargá un respaldo de tus datos actuales.',`<div class="fields"><label class="wide">Archivo de respaldo JSON<input id="restore-file" type="file" accept=".json,application/json" required></label></div><div class="notice" id="restore-preview">Solo admite respaldos de KAPI 3.0. No importa extractos bancarios ni versiones anteriores.</div><button type="button" id="backup-before">Descargar respaldo actual</button>`,'Reemplazar con este respaldo',()=>{if(!incoming)throw Error('Seleccioná un respaldo válido y esperá su lectura.');undo=JSON.parse(JSON.stringify(state));state=incoming;$('#modal').close();persist();render();notify('Respaldo restaurado.',true)});$('#backup-before').onclick=backup;$('#restore-file').onchange=async ev=>{incoming=null;let file=ev.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('El archivo supera los 20 MB.');const data=Core.validate(JSON.parse(await file.text()));incoming=data;$('#restore-preview').textContent=`Respaldo válido: ${data.budgets.length} presupuestos y ${data.expenses.length} gastos. Reemplazará tus datos actuales.`;$('#modal-error').textContent=''}catch(e){$('#modal-error').textContent='No se pudo validar: '+e.message}}}
document.addEventListener('click',ev=>{const n=ev.target.closest('[data-page]');if(n){go(n.dataset.page);return}const el=ev.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){case'new-budget':budgetModal();break;case'edit-budget':budgetModal(id);break;case'add-budget':addBudget(id);break;case'new-expense':expenseModal();break;case'edit-expense':expenseModal(id);break;case'income':go('income-settings');$('#income-form').scrollIntoView({behavior:'smooth'});break;case'all-expenses':go('expenses');break;case'export-csv':exportCSV();break;case'backup':backup();break;case'restore':restore();break}});
$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('kapi.theme',state.theme);commit('Apariencia actualizada.')};$('#display-currency').onchange=ev=>{state.display=ev.target.value;commit('Moneda de visualización actualizada.')};if($('#backup-side'))$('#backup-side').onclick=backup;
render();


// upgrade.js
'use strict';
// The legacy schema is retained so 3.0 backups remain importable.
Core.validate=s=>Finance.migrate(s);
state=Finance.migrate(state);
let session=null,cloudRevision=0,cloudReady=false,cloudBusy=false,dirty=false,config={},chatAnswer='',aiProposal=null;
const guestKey='kapi.v4.guest';
try{const saved=localStorage.getItem(guestKey);if(saved)state=Finance.migrate(JSON.parse(saved))}catch{storageWarning='No se pudo leer el respaldo local 4.0. Descargá tus datos antes de continuar.'}
const oldPersist=persist;
persist=function(){try{Finance.validate(state);if(session){dirty=true;storageWarning='Cambios en esta sesión. Usá Guardar en nube antes de cerrar.'}else{localStorage.setItem(guestKey,JSON.stringify(state));storageWarning=''}return true}catch(e){storageWarning=e.message;return false}};
const oldRender=render;
render=function(){if(['income','account','assistant'].includes(page)){oldRender();$('#app').innerHTML=page==='income'?incomePage():page==='account'?accountPage():assistantPage();bindExtra()}else{oldRender();const toolbar=document.createElement('div');toolbar.className='toolbar extension';toolbar.innerHTML='<button data-extra="receipt">+ Registrar ingreso recibido</button><button data-extra="import">Importar CSV</button><button data-extra="print">PDF / Imprimir</button><button data-extra="excel">Exportar Excel</button>';$('#app').prepend(toolbar);if(page==='home'||page==='reports'){const s=Finance.summary(state,selectedMonth),block=document.createElement('section');block.className='notice';block.textContent=`Ingresos recibidos: ${money(s.received)} · Saldo registrado del mes: ${money(s.netRecorded)}. No incluye saldo inicial ni cuentas sin registrar.`;$('#app').append(block)}if(page==='settings'){const sections=$('#app .settings');sections.lastElementChild.innerHTML='<h2>Conexiones</h2><p>IA y sincronización disponibles al configurar el servidor y tu cuenta. Abrí Mi cuenta para ver el estado.</p><p>Sin conexión bancaria automática. Podés importar movimientos CSV revisando cada lote antes de incorporarlo.</p>';sections.children[2].querySelector('p').textContent=session?'Los datos de tu cuenta permanecen en memoria hasta guardar en nube.':'Modo local: guardado únicamente en este navegador. Descargá respaldos periódicos.'}}
const foot=document.querySelector('.asidefoot p');if(foot)foot.textContent=session?'Cuenta privada · guardado en nube manual':'Modo local · sin conexión bancaria';};
function incomePage(){const s=Finance.summary(state,selectedMonth);return intro('Lo que realmente recibiste.','Separado de tus ingresos previstos y tus presupuestos.',monthControl())+`<div class="toolbar"><button class="primary" data-extra="receipt">+ Registrar ingreso recibido</button><button data-page="settings">Editar calendario de cobros</button></div><div class="card"><p>Recibido este mes</p><div class="stat">${money(s.received)}</div><p class="muted">No se suma automáticamente a la previsión entre cobros.</p></div><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Descripción</th><th>Monto</th><th>Acción</th></tr></thead><tbody>${state.receipts.filter(r=>r.date.slice(0,7)===selectedMonth).map(r=>`<tr><td>${r.date}</td><td>${esc(r.name)}</td><td>${fmt(r.amount,r.currency)}</td><td><button data-extra="receipt" data-id="${esc(r.id)}">Editar</button><button class="danger" data-extra="delete-receipt" data-id="${esc(r.id)}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="4">Todavía no hay cobros registrados.</td></tr>'}</tbody></table></div>`}
function receiptModal(id){const r=state.receipts.find(r=>r.id===id);openModal(r?'Editar ingreso':'Registrar ingreso recibido','Registrá únicamente dinero que ya recibiste.',`<div class="fields"><label class="wide">Descripción<input name="name" required maxlength="100" value="${esc(r?.name||'Sueldo')}"></label><label>Monto<input name="amount" type="number" min="0.01" step="0.01" required value="${r?.amount||''}"></label><label>Moneda<select name="currency">${currencyOptions(r?.currency||state.display)}</select></label><label>Fecha<input name="date" type="date" required max="${today}" value="${r?.date||today}"></label><label>1 USD = Bs<input name="rate" type="number" step="any" min="0.000001" required value="${r?.rate||state.rate}"></label></div>`,'Guardar ingreso',f=>{const date=f.get('date'),currency=f.get('currency');if(!Core.validDate(date)||date>today)throw Error('Fecha inválida');const data={id:r?.id||uid(),name:textValue(f,'name',100),amount:numberValue(f,'amount'),currency,date,rate:currency==='BOB'?1:numberValue(f,'rate')};if(r)Object.assign(r,data);else state.receipts.push(data);selectedMonth=date.slice(0,7);$('#modal').close();commit('Ingreso recibido guardado.')})}
function accountPage(){return intro('Tu espacio privado.','Una cuenta por persona, con datos separados.')+`<section class="card settings"><h2>${session?esc(session.user.email):'Entrar o crear cuenta'}</h2><p class="notice">${!config.supabaseUrl?'Nube sin configurar. El modo local funciona.':session?(dirty?'Tenés cambios pendientes de guardar.':'Cuenta conectada.'):'Nube configurada. Iniciá sesión para usarla.'}</p>${session?`<div class="toolbar"><button data-extra="push" ${cloudReady?'':'disabled'}>Guardar en nube</button><button data-extra="pull">Cargar desde nube</button><button data-extra="upload-local">Importar copia local a esta cuenta</button><button data-extra="logout">Cerrar sesión</button></div><p class="muted">Guardar detecta conflictos entre dispositivos. Cargar reemplaza esta sesión con la copia del servidor después de confirmarlo. Un dispositivo nuevo comienza con la copia de tu cuenta, nunca con datos locales de otra persona.</p>`:`<form id="login-form"><div class="fields"><label>Correo<input name="email" type="email" required autocomplete="email"></label><label>Contraseña<input name="password" type="password" required minlength="12" autocomplete="current-password"></label></div><div class="actions"><button name="mode" value="signup">Crear cuenta</button><button class="primary" name="mode" value="login">Entrar</button></div><p class="muted">Mínimo 12 caracteres. Las sesiones se conservan en memoria: al cerrar la página tendrás que entrar nuevamente.</p></form>`}<div id="account-error" class="error" role="alert"></div></section>`}
function assistantPage(){return intro('Una segunda mirada a tu dinero.','Consultá tus cifras y revisá cada cambio antes de aplicarlo.')+`<section class="card settings"><p class="notice">${config.ai&&session?'IA disponible. Al consultar, autorizás enviar al proveedor IA tu resumen del mes y el texto que escribas. No enviamos descripciones de movimientos.':'IA requiere servidor configurado e inicio de sesión. El análisis local está disponible.'}</p><button data-extra="analyze">Analizar este mes sin IA</button><form id="ai-form"><label>Tu consulta<textarea name="question" maxlength="2000" rows="3" required placeholder="¿Qué presupuesto debería ajustar este mes?"></textarea></label><div class="actions"><button class="primary" ${config.ai&&session&&cloudReady?'':'disabled'}>Consultar IA</button></div></form><p id="ai-status" role="status"></p><div class="answer">${esc(chatAnswer)}</div>${aiProposal?`<div class="notice">Propuesta: ${esc(aiProposal.name)} de ${fmt(aiProposal.before,aiProposal.currency)} a ${fmt(aiProposal.amount,aiProposal.currency)} por mes.<div class="actions"><button data-extra="reject-ai">Descartar</button><button data-extra="confirm-ai">Confirmar cambio</button></div></div>`:''}</section>`}
function bindExtra(){const m=$('#month');if(m)m.onchange=()=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(m.value)){selectedMonth=m.value;render()}};const f=$('#login-form');if(f)f.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{const data=new FormData(f);await login(data.get('email'),data.get('password'),b.value)}catch(e){$('#account-error').textContent=e.message}finally{b.disabled=false}};const ai=$('#ai-form');if(ai)ai.onsubmit=async ev=>{ev.preventDefault();const button=ai.querySelector('button');button.disabled=true;$('#ai-status').textContent='Consultando…';try{if(dirty&&config.aiMode!=='local')throw Error('Guardá tus cambios en nube antes de consultar la IA.');const question=new FormData(ai).get('question');const result=await api(config.aiMode==='local'?'/api/local-assistant':'/api/assistant',config.aiMode==='local'?{question,summary:Finance.summary(state,selectedMonth)}:{question,month:selectedMonth});chatAnswer=result.proposal?'Preparé este ajuste para que lo revises antes de aplicarlo.':result.text;aiProposal=result.proposal?Finance.proposal(state,result.proposal):null;render()}catch(e){$('#ai-status').textContent=e.message;button.disabled=false}}}
async function api(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo completar la solicitud');return data}
async function sb(path,method='GET',body){if(!config.supabaseUrl)throw Error('La nube todavía no está configurada');const r=await fetch(config.supabaseUrl+path,{method,headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>null);if(!r.ok)throw Error(d?.msg||d?.message||d?.error_description||'Error de nube');return d}
async function login(email,password,mode){if(mode==='signup'){const d=await sb('/auth/v1/signup','POST',{email,password});if(!d.access_token){notify('Revisá tu correo para confirmar la cuenta.');return}session=d}else session=await sb('/auth/v1/token?grant_type=password','POST',{email,password});state=Finance.migrate(initial());cloudReady=false;dirty=false;await pull(false);render()}
async function pull(ask=true){if(cloudBusy)return;if(ask&&!confirm('¿Cargar la copia de nube? Los cambios sin guardar de esta sesión se reemplazarán. Descargá antes un respaldo.'))return;cloudBusy=true;try{const rows=await sb('/rest/v1/kapi_documents?select=data,revision');if(rows.length){state=Finance.migrate(rows[0].data);cloudRevision=rows[0].revision}else{state=Finance.migrate(initial());cloudRevision=0}cloudReady=true;dirty=false;storageWarning='';render();notify('Copia de nube cargada.')}finally{cloudBusy=false}}
async function push(){if(cloudBusy||!cloudReady)throw Error('Cargá primero la copia de nube');cloudBusy=true;try{Finance.validate(state);const snapshot=JSON.stringify(state);const rev=await sb('/rest/v1/rpc/save_kapi','POST',{payload:JSON.parse(snapshot),expected_revision:cloudRevision});cloudRevision=rev;dirty=JSON.stringify(state)!==snapshot;storageWarning=dirty?'Quedan cambios pendientes de guardar.':'';render();notify(dirty?'Copia guardada; hay nuevos cambios pendientes.':'Guardado en nube.')}finally{cloudBusy=false}}
function importCSV(){let pending=[];openModal('Importar gastos CSV','Se añaden gastos; nunca se reemplaza tu información.',`<div class="notice">Columnas: fecha,descripcion,monto_original,moneda,tipo_cambio_Bs_por_USD,categoria. Fecha AAAA-MM-DD; decimales con punto; separador coma. USD requiere cambio histórico. Máximo 5000 filas / 2 MB. Exportá un CSV de KAPI como plantilla.</div><label>Archivo CSV<input id="csv-file" type="file" accept=".csv" required></label><pre id="csv-preview" class="answer"></pre>`,'Confirmar importación',()=>{if(!pending.length)throw Error('No hay filas nuevas válidas');undo=JSON.parse(JSON.stringify(state));state.expenses.push(...pending);$('#modal').close();persist();render();notify('Gastos importados.',true)});$('#csv-file').onchange=async e=>{pending=[];try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Máximo 2 MB');const rows=Finance.parseCSV(await file.text());const seen=new Set(state.expenses.map(Finance.signature));let dup=0;for(const r of rows){if(r.date>today)throw Error('No se admiten gastos futuros');const key=Finance.signature(r);if(seen.has(key)){dup++;continue}seen.add(key);pending.push({...r,id:uid()})}$('#csv-preview').textContent=pending.length+' nuevos · '+dup+' duplicados omitidos\n'+pending.slice(0,8).map(r=>r.date+' · '+r.name+' · '+fmt(r.amount,r.currency)).join('\n');$('#modal-error').textContent=''}catch(err){pending=[];$('#modal-error').textContent=err.message}}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-extra]');if(!el)return;try{switch(el.dataset.extra){case'receipt':receiptModal(el.dataset.id);break;case'delete-receipt':if(confirm('¿Eliminar este ingreso recibido?')){state.receipts=state.receipts.filter(r=>r.id!==el.dataset.id);commit('Ingreso eliminado.')}break;case'import':importCSV();break;case'excel':{await loadKapiScript('xlsx.js');const rows=[['Tipo','Fecha','Descripción','Monto original','Moneda','Cambio Bs/USD','Equivalente Bs'],...state.expenses.filter(r=>r.date.slice(0,7)===selectedMonth).map(r=>['Gasto',r.date,r.name,r.amount,r.currency,r.rate,Core.bs(r.amount,r.currency,r.rate)]),...state.receipts.filter(r=>r.date.slice(0,7)===selectedMonth).map(r=>['Ingreso',r.date,r.name,r.amount,r.currency,r.rate,Core.bs(r.amount,r.currency,r.rate)])];download('KAPI_'+selectedMonth+'.xlsx',KapiXlsx(rows),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;}case'print':window.print();break;case'push':await push();break;case'pull':await pull();break;case'upload-local':if(!cloudReady)throw Error('Cargá primero la cuenta');if(confirm('¿Reemplazar esta sesión por los datos del modo local? Después usá Guardar en nube.')){const raw=localStorage.getItem(guestKey);if(!raw)throw Error('No hay copia local');state=Finance.migrate(JSON.parse(raw));commit('Copia local cargada en esta sesión. Revisala antes de guardar en nube.')}break;case'logout':if(dirty&&!confirm('Hay cambios sin guardar. ¿Cerrar sesión igualmente?'))return;await sb('/auth/v1/logout','POST',{}).catch(()=>{});session=null;cloudReady=false;dirty=false;state=Finance.migrate(initial());const raw=localStorage.getItem(guestKey);if(raw)state=Finance.migrate(JSON.parse(raw));storageWarning='';chatAnswer='';aiProposal=null;render();break;case'analyze':{const s=Finance.summary(state,selectedMonth);chatAnswer=`Gastos registrados: ${money(s.spent)}. Ingresos recibidos: ${money(s.received)}. Saldo registrado: ${money(s.netRecorded)}.\n`+s.budgets.filter(b=>b.spent>b.limit).map(b=>b.name+': excedido en '+money(b.spent-b.limit)).join('\n')+'\nLos ingresos previstos no son dinero recibido. El saldo no incluye cuentas sin registrar.';render();break}case'reject-ai':aiProposal=null;render();break;case'confirm-ai':{const p=Finance.proposal(state,aiProposal),b=state.budgets.find(b=>b.id===p.id);if(b.amount!==aiProposal.before)throw Error('El presupuesto cambió. Consultá nuevamente.');b.amount=p.amount;aiProposal=null;commit(session?'Cambio confirmado. Guardá en nube para sincronizarlo.':'Cambio confirmado y guardado en este dispositivo.');break}}}catch(err){notify(err.message)}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if(!window.KAPI_STATIC_BETA)fetch('/api/config').then(r=>r.json()).then(c=>{config=c;if(page==='account'||page==='assistant')render()}).catch(()=>{});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).catch(()=>{});
render();


// catalog.js
(function(root){
const groups={
'Hogar':[['🏠','Alquiler / vivienda'],['💡','Luz, agua y gas'],['📶','Internet'],['🛠️','Mantenimiento del hogar'],['🧹','Limpieza y hogar']],
'Día a día':[['🛒','Supermercado'],['🥗','Alimentación'],['🍽️','Restaurantes'],['🛵','Delivery'],['☕','Café y snacks'],['📱','Celular']],
'Movilidad':[['🚌','Transporte público'],['🚕','Taxis'],['⛽','Combustible'],['🚗','Auto y mantenimiento'],['🅿️','Estacionamiento']],
'Bienestar':[['🩺','Salud y consultas'],['💊','Medicamentos'],['🛡️','Seguros'],['🏋️','Gimnasio y deporte'],['💇','Cuidado personal']],
'Familia y aprendizaje':[['🎓','Educación'],['📚','Cursos y libros'],['🧸','Hijos y cuidado'],['🤝','Apoyo familiar'],['🐾','Mascotas']],
'Estilo de vida':[['🎬','Ocio y salidas'],['👕','Ropa y calzado'],['📺','Suscripciones'],['🎮','Gaming'],['✈️','Viajes'],['🎁','Regalos'],['❤️','Donaciones'],['💻','Tecnología']],
'Compromisos':[['💳','Tarjeta y cuotas'],['🏦','Préstamos y deudas'],['🧾','Impuestos'],['💼','Trabajo / negocio'],['🧰','Imprevistos'],['➕','Otros gastos']]
};
const items=Object.entries(groups).flatMap(([group,rows])=>rows.map(([icon,name])=>({group,icon,name})));
function health(limit,spent){if(!Number.isFinite(limit)||!Number.isFinite(spent)||spent<0||limit<0)throw Error('Cifras inválidas');const remaining=limit-spent,ratio=limit>0?Math.max(0,Math.min(1,remaining/limit)):0;return {remaining,ratio,percent:Math.round(ratio*100),status:limit===0?'empty':ratio>.5?'green':ratio>.2?'yellow':'red',label:limit===0?'Sin límite':remaining<0?'Límite superado':ratio>.5?'Vas bien':ratio>.2?'Cuidá el ritmo':'Queda poco'}}
function filter(query){const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return items.filter(x=>norm(x.name+' '+x.group).includes(norm(query.trim())))}
root.KapiCatalog={items,health,filter};
})(typeof window==='undefined'?globalThis:window);


// friendly.js
'use strict';
// A single rendering layer replaces the legacy and 4.0 screens. Data and tested actions stay shared.
let movementTab='expenses',catalogQuery='';
function ring(limit,spent,compact=false){const h=KapiCatalog.health(limit,spent),radius=45,length=2*Math.PI*radius;return `<div class="budget-ring ${h.status} ${compact?'compact':''}" role="img" aria-label="${h.percent}% disponible. ${esc(h.label)}. Gastado ${money(spent)} de ${money(limit)}"><svg viewBox="0 0 110 110" aria-hidden="true"><circle class="ring-track" cx="55" cy="55" r="45"/><circle class="ring-value" cx="55" cy="55" r="45" stroke-dasharray="${length}" stroke-dashoffset="${length*(1-h.ratio)}" transform="rotate(-90 55 55)"/></svg><div class="ring-center"><strong>${limit?h.percent+'%':'—'}</strong><small>disponible</small></div></div>`}
function generalLimit(){return state.generalBudget?Core.bs(state.generalBudget.amount,state.generalBudget.currency,state.rate):totals().planned}
function iconFor(name){return KapiCatalog.items.find(x=>x.name===name)?.icon||({'Alimentación':'🥗','Transporte':'🚌','Vida y ocio':'🎬'}[name])||'◇'}
function friendlyBudgetCards(list=state.budgets){const {from,to}=Core.bounds(selectedMonth);return list.length?`<div class="budgets">${list.map(b=>{const spent=Core.spend(state,from,to,b.id),limit=Core.bs(b.amount,b.currency,state.rate),h=KapiCatalog.health(limit,spent);return `<article class="card budget-card ${h.status}" data-budget-id="${esc(b.id)}"><div class="row"><h3><span class="category-emoji">${iconFor(b.name)}</span>${esc(b.name)}</h3><button class="subtle" data-action="edit-budget" data-id="${esc(b.id)}" aria-label="Editar ${esc(b.name)}">Editar</button></div><div class="budget-content">${ring(limit,spent,true)}<div><small class="muted">${h.remaining<0?'Te excediste en':'Te quedan'}</small><div class="amount">${money(Math.abs(h.remaining))}</div><small class="muted">de ${fmt(b.amount,b.currency)} al mes</small></div></div><div class="budgetfoot"><button type="button" data-budget-details="${esc(b.id)}" aria-label="Ver gastos de ${esc(b.name)}">Ver gastos</button><span class="health-label ${h.status}">${h.label}</span><button data-action="add-budget" data-id="${esc(b.id)}">+ Aumentar monto</button><button class="danger" data-plan="delete-budget" data-id="${esc(b.id)}" aria-label="Eliminar ${esc(b.name)}">Eliminar</button></div></article>`}).join('')}</div>`:'<div class="empty card">Podés usar solo el límite general o crear categorías para organizarte mejor.</div>'}
function friendlyHome(){const t=totals(),limit=generalLimit(),h=KapiCatalog.health(limit,t.spent),a=Core.available(state,today);return intro('Tu mes, más claro.','Lo importante, de un vistazo.',monthControl())+`<section class="overview card"><div class="overview-copy"><span class="eyebrow">${state.generalBudget?'Tu límite general':'Total de tus categorías'} · ${esc(titleMonth(selectedMonth))}</span><h2>${limit?(h.remaining<0?'Superaste tu plan por':'Te queda para este mes'):'Empezá con un límite mensual'}</h2><div class="balance">${limit?money(Math.abs(h.remaining)):'Vos elegís el monto'}</div><p class="muted">${limit?money(t.spent)+' gastados de '+money(limit):'Podés planificar en Bs o USD, con o sin categorías.'}</p><button data-friendly="general">${limit?'Cambiar límite general':'Definir mi presupuesto'}</button><div class="health-label ${h.status}">${h.label}</div></div>${ring(limit,t.spent)}</section><div class="mini-stats"><div><small>Ingresos recibidos</small><strong>${money(Finance.summary(state,selectedMonth).received)}</strong></div><div><small>Gastos del mes</small><strong>${money(t.spent)}</strong></div><div><small>Próximo cobro previsto</small><strong>${short(a.end)}</strong><span class="muted">${fmt(state.income.amount,state.income.currency)}</span></div></div><div class="sectionhead"><h2>Tus categorías</h2><button class="subtle" data-page="budgets">Ver y organizar →</button></div>${friendlyBudgetCards(state.budgets.slice(0,3))}<p class="tag">El límite es un plan de gasto, no tu saldo bancario. El próximo cobro es una previsión.</p>`}
function friendlyBudgets(){const t=totals();return intro('Un presupuesto a tu medida.','Un límite general y las categorías que vos elijas.',monthControl())+`<section class="card general-plan"><div><span class="eyebrow">Límite general del mes</span><h2>${state.generalBudget?fmt(state.generalBudget.amount,state.generalBudget.currency):'Sin límite independiente'}</h2><p class="muted">${state.generalBudget?'Incluye todos tus gastos, también los que no tienen categoría.':'La rueda usa por ahora la suma de tus categorías.'}</p></div><button data-friendly="general">${state.generalBudget?'Editar límite':'Definir límite'}</button></section><div class="sectionhead"><div><h2>Elegí tus categorías</h2><p class="muted">No hace falta usar todas. Podés crear cualquier otra.</p></div><button class="primary" data-action="new-budget">+ Crear presupuesto</button></div>${friendlyBudgetCards()}${state.generalBudget&&t.planned>generalLimit()?'<p class="notice">Tus categorías suman más que el límite general. Ajustalas para que tu plan sea consistente.</p>':''}`}
function friendlyMovements(){return intro('Tus movimientos.','Gastos e ingresos, sin mezclarlos.',monthControl())+`<div class="segment" role="group" aria-label="Tipo de movimientos"><button data-friendly="tab-expenses" class="${movementTab==='expenses'?'selected':''}">Gastos</button><button data-friendly="tab-income" class="${movementTab==='income'?'selected':''}">Ingresos recibidos</button></div>${movementTab==='expenses'?expenseTable():`<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Ingreso</th><th>Monto</th><th></th></tr></thead><tbody>${state.receipts.filter(r=>r.date.slice(0,7)===selectedMonth).sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${r.date}</td><td>${esc(r.name)}${r.source==='scheduled'?'<small class="tag"> · Programado automáticamente</small>':''}</td><td>${fmt(r.amount,r.currency)}</td><td><button data-extra="receipt" data-id="${esc(r.id)}">Editar</button><button class="subtle danger" data-extra="delete-receipt" data-id="${esc(r.id)}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Todavía no registraste ingresos en este mes.</td></tr>'}</tbody></table></div>`}`}
function friendlySettings(){return intro('Ajustes y herramientas.','Tu cuenta y las opciones que usás de vez en cuando.')+`<div class="settings"><section class="card"><h2>Tu espacio</h2><p class="muted">${session?'Cuenta privada: '+esc(session.user.email):'Usás KAPI en este dispositivo. No hace falta una cuenta para registrar tus gastos.'}</p><div class="toolbar"><button data-page="account">${session?'Mi cuenta y sincronización':'Conectar mi cuenta'}</button><button data-page="income-settings">Ingresos previstos y monedas</button><button data-page="reports">Ver informes</button></div></section><section class="card"><h2>Importar y descargar</h2><p class="muted">Importá gastos o descargá los registros del mes que tengas seleccionado.</p><div class="toolbar"><button data-extra="import">Importar CSV</button><button data-action="export-csv">Descargar CSV</button><button data-extra="excel">Descargar Excel</button><button data-extra="print">PDF / Imprimir</button></div></section><section class="card"><h2>Respaldo de tus datos</h2><div class="toolbar"><button data-action="backup">Descargar respaldo</button><button data-action="restore">Restaurar respaldo</button></div><p class="tag">Guardá una copia antes de cambiar de dispositivo o navegador.</p></section></div>`}
const originalSettings=settings;
render=function(){if(page==='income'){page='expenses';movementTab='income'}if(page==='settings')page='tools';document.body.classList.toggle('dark',state.theme==='dark');$('#display-currency').value=state.display;$('#theme').setAttribute('aria-label',state.theme==='dark'?'Activar modo claro':'Activar modo oscuro');$('#theme').textContent=state.theme==='dark'?'☀':'◐';$('#today').textContent=new Intl.DateTimeFormat('es-BO',{day:'numeric',month:'long',year:'numeric'}).format(Core.parse(today));document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});let html=page==='home'?friendlyHome():page==='budgets'?friendlyBudgets():page==='expenses'?friendlyMovements():page==='assistant'?assistantPage():page==='account'?accountPage():page==='reports'?reports():page==='income-settings'?originalSettings():friendlySettings();$('#app').innerHTML=(storageWarning?`<div class="notice warning" role="status">${esc(storageWarning)}</div>`:'')+html;const mc=$('#month');if(mc)mc.onchange=()=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(mc.value)){selectedMonth=mc.value;render()}};if(page==='income-settings'){bindSettings();const sections=$('#app .settings');while(sections.children.length>2)sections.lastElementChild.remove()}if(['account','assistant'].includes(page))bindExtra();const foot=document.querySelector('.asidefoot p');if(foot)foot.textContent=session?'Tu cuenta privada':'Guardado en este dispositivo';};
function generalModal(){const b=state.generalBudget;openModal('Tu presupuesto general','El máximo que querés gastar al mes. No modifica tus ingresos ni duplica los presupuestos por categoría.',`<div class="fields"><label>Monto mensual<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" value="${b?.amount||''}" required></label><label>Moneda<select name="currency">${currencyOptions(b?.currency||state.display)}</select></label></div>`,'Guardar límite',f=>{state.generalBudget={amount:numberValue(f,'amount'),currency:f.get('currency')};$('#modal').close();commit('Tu límite general está listo.')},b?'<button type="button" class="subtle" id="remove-general">Usar suma de categorías</button>':'');if(b)$('#remove-general').onclick=()=>{state.generalBudget=null;$('#modal').close();commit('La rueda vuelve a usar la suma de tus categorías.')}}
const editBudgetOriginal=budgetModal;
budgetModal=function(id){if(id){editBudgetOriginal(id);return}openModal('¿Para qué querés presupuestar?','Elegí una categoría o creá la tuya. Después definís el monto.',`<label>Buscar categoría<input id="category-search" type="search" placeholder="Ej. alquiler, salud, mascotas" autocomplete="off"></label><div id="category-options" class="category-grid"></div>`,'Crear otra categoría',()=>customBudget());const draw=()=>{const items=KapiCatalog.filter($('#category-search').value);$('#category-options').innerHTML=items.map(item=>`<button type="button" data-preset="${KapiCatalog.items.indexOf(item)}"><span>${item.icon}</span><strong>${esc(item.name)}</strong><small>${esc(item.group)}</small></button>`).join('')||'<p class="muted">No encontramos esa categoría. Podés crearla abajo.</p>'};$('#category-search').oninput=draw;draw()};
function customBudget(item){$('#modal').close();openModal(item?'Presupuesto de '+esc(item.name):'Tu propia categoría','Podés cambiar el nombre y el monto cuando quieras.',`<div class="fields"><label class="wide">Nombre<input name="name" maxlength="70" required value="${esc(item?.name||'')}" placeholder="Ej. Mi emprendimiento"></label><label>Monto mensual<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" required placeholder="Ej. 500"></label><label>Moneda<select name="currency">${currencyOptions(state.display)}</select></label><input type="hidden" name="category" value="${esc(item?.group||'Personalizada')}"></div>`,'Crear presupuesto',f=>{const name=textValue(f,'name',70);if(state.budgets.some(b=>b.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Ya tenés una categoría con ese nombre. Podés editarla o usar otro nombre.');state.budgets.push({id:uid(),name,category:textValue(f,'category',70),amount:numberValue(f,'amount'),currency:f.get('currency')});$('#modal').close();commit('Presupuesto creado.');})}
function movementChooser(){openModal('¿Qué querés registrar?','Elegí el tipo de movimiento.',`<div class="movement-choice"><button type="button" data-friendly="new-expense"><span>↗</span><strong>Un gasto</strong><small>Dinero que salió</small></button><button type="button" data-friendly="new-income"><span>↙</span><strong>Un ingreso</strong><small>Dinero que recibiste</small></button></div>`,'Cancelar',()=>$('#modal').close());$('#modal-form .actions').remove()}
document.addEventListener('click',e=>{const preset=e.target.closest('[data-preset]');if(preset){customBudget(KapiCatalog.items[Number(preset.dataset.preset)]);return}const action=e.target.closest('[data-friendly]')?.dataset.friendly;if(!action)return;if(action==='general')generalModal();if(action==='movement')movementChooser();if(action==='new-expense'){$('#modal').close();expenseModal()}if(action==='new-income'){$('#modal').close();receiptModal()}if(action==='tab-expenses'){movementTab='expenses';render()}if(action==='tab-income'){movementTab='income';render()}});

render();
assistantPage=function(){const available=config.ai&&(config.aiMode==='local'||(session&&cloudReady));return intro('Hablemos de tu dinero.','Preguntá con tus palabras. Vos decidís cada cambio.',monthControl())+`<section class="card settings"><div class="ai-state"><span class="dot"></span><strong>${available?(config.aiMode==='local'?'IA local conectada':'IA conectada'):'Conectá tu asistente'}</strong></div><p class="muted">${available?(config.aiMode==='local'?'Tus cifras se procesan en esta Mac, sin clave de API.':'Al consultar, compartís el resumen del mes con el proveedor de IA.'):(location.protocol==='file:'?'La IA necesita la aplicación abierta con el servidor local. Usá «Iniciar KAPI con IA.command» en la carpeta del proyecto.':'Abrí «Iniciar KAPI con IA.command» para encender el asistente en esta Mac. No necesita una cuenta KAPI.')}</p>${!available?'<button data-friendly="check-ai">Comprobar conexión</button>':''}${location.protocol==='file:'?'<p><a href="http://localhost:3000">Abrir KAPI con IA en esta Mac →</a></p>':''}<div class="ai-chips"><button data-question="¿Cómo voy este mes?">¿Cómo voy este mes?</button><button data-question="¿En qué categoría estoy gastando más?">¿Dónde gasto más?</button><button data-question="¿Qué puedo ajustar para gastar menos?">Ayudame a ajustar mi plan</button></div><form id="ai-form"><label>¿Qué querés saber?<textarea name="question" rows="3" maxlength="2000" placeholder="Ej. ¿Cuánto me queda para gastar este mes?" required></textarea></label><div class="actions"><button class="primary" ${available?'':'disabled'}>Enviar consulta</button></div></form><p id="ai-status" role="status"></p>${chatAnswer?'<div class="ai-response">'+esc(chatAnswer)+'</div>':''}${aiProposal?`<div class="notice"><strong>Revisá este cambio antes de aplicarlo</strong><p>${esc(aiProposal.name)}: ${fmt(aiProposal.before,aiProposal.currency)} → ${fmt(aiProposal.amount,aiProposal.currency)} al mes.</p><div class="actions"><button data-extra="reject-ai">Descartar</button><button data-extra="confirm-ai">Confirmar cambio</button></div></div>`:''}</section>`};
document.addEventListener('click',async e=>{const chip=e.target.closest('[data-question]');if(chip){const input=$('#ai-form textarea');if(input){input.value=chip.dataset.question;input.focus()}}if(e.target.closest('[data-friendly="check-ai"]')){try{const r=await fetch('/api/config');if(!r.ok)throw Error();config=await r.json();render();notify(config.ai?'Asistente conectado.':'La IA todavía no está lista. Abrí el iniciador local.')}catch{notify('Abrí la aplicación desde Iniciar KAPI con IA.command.')}}});
render();

const accountWithProvider=accountPage;accountPage=function(){if(config.supabaseUrl)return accountWithProvider();return intro('Tu cuenta KAPI.','Es opcional para usar esta Mac.')+'<section class="card settings"><h2>Por ahora, tus datos están en este dispositivo</h2><p>Podés registrar gastos, crear presupuestos y usar la IA local sin iniciar sesión.</p><p class="muted">Para sincronizar entre dispositivos hay que configurar el servicio de cuentas. No ingreses un correo ni una contraseña hasta conectarlo.</p><button data-page="home">Volver al inicio</button></section>'};
render();
const expenseBeforeFriendly=expenseModal;
expenseModal=function(id){expenseBeforeFriendly(id);const input=$('#free-category input');if(input){input.setAttribute('list','expense-category-catalog');const list=document.createElement('datalist');list.id='expense-category-catalog';list.innerHTML=KapiCatalog.items.map(item=>'<option value="'+esc(item.name)+'">').join('');$('#modal-form').append(list)}};
const receiptBeforeFriendly=receiptModal;
receiptModal=function(id){receiptBeforeFriendly(id);const currency=$('#modal select[name="currency"]'),rate=$('#modal input[name="rate"]');const toggle=()=>{rate.closest('label').hidden=currency.value==='BOB';rate.disabled=currency.value==='BOB'};currency.onchange=toggle;toggle()};


// pwa.js
'use strict';
let installPrompt=null;
function isInstalled(){return window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function installHelp(){const ios=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);return ios?'<ol><li>Abrí el enlace de KAPI en Safari.</li><li>Tocá <strong>Compartir</strong>.</li><li>Elegí <strong>Añadir a pantalla de inicio</strong> y confirmá.</li></ol>':'<ol><li>Abrí el enlace de KAPI en Chrome en tu celular.</li><li>Tocá el menú <strong>⋮</strong>.</li><li>Elegí <strong>Instalar aplicación</strong> o <strong>Añadir a pantalla de inicio</strong>.</li></ol>'}
async function installKapi(){if(isInstalled()){notify('KAPI ya está abierto como aplicación.');return}if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();const result=await prompt.userChoice;if(result.outcome==='accepted')notify('Seguí los pasos de instalación de tu celular.');return}openModal('KAPI en tu celular','Un icono propio para entrar directo, como con tus otras apps.',`<div class="notice">${location.protocol==='file:'?'Para instalarla primero hay que publicar KAPI con un enlace HTTPS. Este archivo local no se instala como app.':'La instalación requiere abrir KAPI en el navegador del celular. Si llegaste desde WhatsApp, abrí el enlace en Safari o Chrome.'}</div>${installHelp()}<p class="muted">Tus registros se guardan en este dispositivo. Podés descargar un respaldo desde Ajustes. La IA necesita su conexión aparte.</p>`,'Entendido',()=>$('#modal').close());$('#modal-form .cancel').remove()}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;if(page==='home')render()});
window.addEventListener('appinstalled',()=>{installPrompt=null;if(page==='home')render();notify('KAPI instalada. Ya podés abrirla desde su icono.')});
const renderBeforeInstall=render;
render=function(){renderBeforeInstall();if(page==='home'&&!isInstalled()){const banner=document.createElement('section');banner.className='install-banner';banner.innerHTML='<div><strong>KAPI, a un toque</strong><p>Agregala a la pantalla de inicio de tu celular.</p></div><button data-install-kapi>Instalar app</button>';$('#app').prepend(banner)}if(page==='tools'){const box=document.createElement('section');box.className='card';box.innerHTML='<h2>Instalar KAPI</h2><p class="muted">Abrila desde su propio icono en tu celular.</p><button data-install-kapi>'+(isInstalled()?'Ver instalación':'Cómo instalar')+'</button>';$('#app .settings').prepend(box)}};
document.addEventListener('click',e=>{if(e.target.closest('[data-install-kapi]'))installKapi().catch(()=>notify('Usá el menú del navegador para añadir KAPI a tu pantalla de inicio.'))});
window.addEventListener('online',()=>notify('Volviste a tener conexión.'));
window.addEventListener('offline',()=>notify('Sin conexión: podés seguir registrando tus gastos en este dispositivo. La IA y la nube necesitan conexión.'));
render();
const KAPI_RELEASE=window.KAPI_RELEASE;
let nextRelease=null;
async function checkKapiUpdate(){if(location.protocol==='file:'||document.visibilityState==='hidden')return;try{const url=new URL('version.json',location.href);url.searchParams.set('check',String(Math.floor(Date.now()/60000)));const response=await fetch(url,{cache:'no-store'});if(!response.ok)return;const release=await response.json();if(typeof release.version!=='string'||!/^\d+\.\d+\.\d+$/.test(release.version)||release.version===KAPI_RELEASE)return;const newer=release.version.split('.').reduce((n,x)=>n*1000+Number(x),0)>KAPI_RELEASE.split('.').reduce((n,x)=>n*1000+Number(x),0);if(!newer)return;nextRelease=release.version;if(!$('#kapi-update-banner')){const banner=document.createElement('div');banner.id='kapi-update-banner';banner.className='update-banner';banner.setAttribute('role','status');banner.innerHTML='<span>Hay una nueva versión de KAPI.</span><button data-update-kapi>Actualizar</button>';document.body.append(banner)}}catch{}}
async function updateKapi(){if(typeof dirty!=='undefined'&&dirty){notify('Guardá tus cambios en tu cuenta antes de actualizar.');return}try{const registration=await navigator.serviceWorker?.getRegistration();if(registration?.waiting)registration.waiting.postMessage({type:'ACTIVATE_UPDATE'});await registration?.update();if(registration?.waiting)registration.waiting.postMessage({type:'ACTIVATE_UPDATE'});const url=new URL(location.href);url.searchParams.set('v',nextRelease||KAPI_RELEASE);url.searchParams.set('refresh',Date.now());location.replace(url.href)}catch{notify('No se pudo actualizar. Cerrá y volvé a abrir KAPI.')}}
async function shareKapi(){const url=location.protocol==='file:'?'https://emiliozorrilla-droid.github.io/kapi/':location.origin+location.pathname;if(navigator.share){try{await navigator.share({title:'KAPI — Tus presupuestos',text:'Abrí KAPI y agregala a tu pantalla de inicio.',url})}catch(error){if(error.name!=='AbortError')notify('Podés compartir este enlace: '+url)}}else{try{await navigator.clipboard.writeText(url);notify('Enlace copiado. Ya podés enviarlo.')}catch{notify('Compartí este enlace: '+url)}}}
document.addEventListener('click',event=>{if(event.target.closest('[data-update-kapi]'))updateKapi();if(event.target.closest('[data-share-kapi]'))shareKapi()});
const renderWithShare=render;
render=function(){renderWithShare();if(page==='tools'){const target=$('#app .settings .card');if(target&&!target.querySelector('[data-share-kapi]')){const button=document.createElement('button');button.dataset.shareKapi='';button.textContent='Compartir KAPI';target.append(button)}const card=document.createElement('section');card.className='card';card.innerHTML='<h2>Actualizar KAPI</h2><p>Versión '+KAPI_RELEASE+'. Cargá la versión publicada sin borrar tus registros.</p><button data-update-kapi>Actualizar ahora</button>';$('#app').prepend(card)}};
window.addEventListener('online',checkKapiUpdate);
window.addEventListener('visibilitychange',checkKapiUpdate);
setInterval(checkKapiUpdate,5*60*1000);
checkKapiUpdate();
render();


// cloud-document.js
(function(root){
const clone=s=>JSON.parse(JSON.stringify(s));
class CloudDocument{
 constructor({client,storage,validate,initial,onChange=()=>{}}){Object.assign(this,{client,storage,validate,initial,onChange});this.owner=null;this.data=null;this.revision=0;this.pending=false;this.conflict=false;this.flight=null;this.generation=0;this.epoch=0}
 key(){return 'kapi.account.'+this.owner}
 attach(id){this.epoch++;this.owner=id;this.data=null;this.revision=0;this.pending=false;this.conflict=false;this.flight=null;this.generation=0;const raw=this.storage.getItem(this.key());if(raw){const c=JSON.parse(raw);this.data=this.validate(c.data);if(!Number.isSafeInteger(c.revision)||c.revision<0)throw Error('Copia local inválida');this.revision=c.revision;this.pending=c.pending===true}return this.data&&clone(this.data)}
 cache(){if(!this.owner)throw Error('No hay cuenta');this.storage.setItem(this.key(),JSON.stringify({data:this.data,revision:this.revision,pending:this.pending}))}
 async load(force=false){const epoch=this.epoch,id=this.owner;if(!id)throw Error('Iniciá sesión');const {data,error}=await this.client.from('kapi_documents').select('data,revision').eq('user_id',id).maybeSingle();if(epoch!==this.epoch)throw Error('La cuenta cambió');if(error)throw error;if(this.pending&&!force){if((data?.revision||0)!==this.revision)this.conflict=true;this.onChange();return clone(this.data)}this.data=data?this.validate(data.data):this.validate(this.initial());this.revision=data?.revision||0;this.pending=false;this.conflict=false;this.cache();this.onChange();return clone(this.data)}
 write(data){if(!this.owner||!this.data)throw Error('Esperá a que termine de cargar tu cuenta');this.data=this.validate(clone(data));this.pending=true;this.generation++;this.cache();this.onChange()}
 async push(){if(this.flight)return this.flight;if(!this.pending)return;if(this.conflict)throw Error('Hay cambios en otro dispositivo. Revisá el conflicto.');const epoch=this.epoch,id=this.owner,generation=this.generation,payload=clone(this.data),revision=this.revision;if(!id)throw Error('Iniciá sesión');this.flight=(async()=>{const {data,error}=await this.client.rpc('save_kapi',{payload,expected_revision:revision});if(epoch!==this.epoch)throw Error('La cuenta cambió');if(error){if(error.code==='P0001'||/conflicto/i.test(error.message||''))this.conflict=true;this.onChange();throw error}if(!Number.isSafeInteger(data)||data<=revision)throw Error('Revisión de nube inválida');this.revision=data;this.pending=this.generation!==generation;this.cache();this.onChange()})().finally(()=>{if(epoch===this.epoch)this.flight=null});return this.flight}
 detach({removeCache=false}={}){if(removeCache&&this.owner)this.storage.removeItem(this.key());this.epoch++;this.owner=null;this.data=null;this.pending=false;this.conflict=false;this.flight=null}
}
root.CloudDocument=CloudDocument;
})(typeof window==='undefined'?globalThis:window);


// accounts.js
'use strict';
let accountClient=null,accountDoc=null,accountMode='login',accountMessage='',accountLoading=false,recoveringPassword=false,accountTimer=null,accountSwitch=0;
const accountSettings=window.KAPI_ACCOUNT_CONFIG||{};
const accountEnabled=!!(accountSettings.url&&accountSettings.publicKey);
const accountReturn=()=>location.origin+location.pathname;
function accountStatus(){if(accountLoading)return 'Cargando tu cuenta…';if(!session)return 'Solo en este dispositivo';if(accountDoc?.conflict)return 'Hay cambios en otro dispositivo';if(dirty)return navigator.onLine?'Guardado pendiente':'Sin conexión · guardado en este dispositivo';return 'Guardado en tu cuenta'}
function accountPaint(){const target=$('#account-sync-status');if(target)target.textContent=accountStatus();if(page==='account')render()}
function queueAccountSave(){clearTimeout(accountTimer);if(!session||!cloudReady||accountDoc?.conflict||!navigator.onLine)return;accountTimer=setTimeout(()=>push().catch(()=>accountPaint()),900)}
const devicePersist=persist;
persist=function(){if(!session)return devicePersist();try{Finance.validate(state);accountDoc.write(state);dirty=true;storageWarning='';queueAccountSave();accountPaint();return true}catch(error){storageWarning='No se pudo guardar. Descargá un respaldo antes de cerrar.';return false}};
push=async function(){if(!accountDoc||!cloudReady)throw Error('Esperá a que cargue tu cuenta');await accountDoc.push();dirty=accountDoc.pending;accountPaint();if(dirty)queueAccountSave()};
pull=async function(ask=true){if(!accountDoc)throw Error('Iniciá sesión');if(ask&&!confirm('¿Cargar la versión de tu cuenta? Primero descargá un respaldo si tenés cambios pendientes.'))return;state=await accountDoc.load(ask);cloudReady=true;dirty=accountDoc.pending;render();queueAccountSave()};
function deviceState(){const raw=localStorage.getItem(guestKey);return raw?Finance.migrate(JSON.parse(raw)):Finance.migrate(initial())}
async function activateAccount(next){const previousUser=session?.user?.id;session=next;if(previousUser!==next?.user?.id)window.dispatchEvent(new Event('kapi-account-changed'));if(accountDoc?.owner===next?.user?.id){accountPaint();return}const sequence=++accountSwitch;clearTimeout(accountTimer);chatAnswer='';aiProposal=null;undo=null;cloudReady=false;dirty=false;if(!next){accountDoc?.detach();state=deviceState();storageWarning='';accountLoading=false;render();return}accountLoading=true;state=Finance.migrate(initial());try{const cached=accountDoc.attach(next.user.id);if(cached){state=cached;cloudReady=true;dirty=accountDoc.pending}render();const loaded=await accountDoc.load();if(sequence!==accountSwitch)return;state=loaded;cloudReady=true;dirty=accountDoc.pending;accountMessage='';queueAccountSave()}catch(error){if(sequence!==accountSwitch)return;accountMessage=cloudReady?'No pudimos conectar. Tu copia personal sigue en este dispositivo.':'No pudimos cargar tu cuenta. Revisá la conexión y volvé a intentar.'}finally{if(sequence===accountSwitch){accountLoading=false;render()}}}
accountPage=function(){if(!accountEnabled)return intro('Tu cuenta personal.','Para guardar tus gastos entre dispositivos.')+'<section class="card settings"><h2>Conexión pendiente de activar</h2><p>El registro personal está preparado, pero todavía falta conectar el servicio de cuentas. Por ahora tus datos siguen en este dispositivo.</p><button data-page="home">Volver al inicio</button></section>';if(session&&recoveringPassword)return intro('Elegí tu nueva contraseña.','Usá una contraseña que no compartas con otras aplicaciones.')+`<section class="card settings"><form id="password-recovery"><label>Nueva contraseña<input type="password" name="password" autocomplete="new-password" minlength="12" required></label><label>Repetir contraseña<input type="password" name="confirm" autocomplete="new-password" minlength="12" required></label><div class="actions"><button class="primary">Guardar contraseña</button></div></form><p class="error" id="account-error" role="alert">${esc(accountMessage)}</p></section>`;if(session)return intro('Tu cuenta personal.','Tus registros están separados de los demás.')+`<section class="card settings"><h2>${esc(session.user.email||'Mi cuenta')}</h2><p class="notice" id="account-sync-status">${esc(accountStatus())}</p>${accountDoc?.conflict?'<p>Otro dispositivo guardó una versión más nueva. Descargá tu copia antes de elegir qué conservar.</p><div class="toolbar"><button data-account="backup">Descargar mi copia pendiente</button><button data-account="resolve">Cargar versión de mi cuenta</button></div>':'<div class="toolbar"><button data-account="sync" '+(cloudReady?'':'disabled')+'>Guardar ahora</button><button data-account="reload">Actualizar mis datos</button></div>'}<div class="toolbar"><button data-account="migrate">Importar datos de este dispositivo</button><button data-account="logout">Cerrar sesión</button></div><p class="muted">Los cambios se guardan automáticamente. Sin conexión se conservan en una copia de esta cuenta en el dispositivo y se reintentan al volver a conectar.</p><p class="error" id="account-error" role="alert">${esc(accountMessage)}</p></section>`;return intro(accountMode==='signup'?'Creá tu cuenta KAPI.':accountMode==='recover'?'Recuperá tu acceso.':'Entrá a tu espacio.','Tus gastos y presupuestos, solo para vos.')+`<section class="card settings"><form id="personal-login"><label>Correo<input name="email" type="email" autocomplete="email" required maxlength="254"></label>${accountMode==='recover'?'':`<label>Contraseña<input name="password" type="password" autocomplete="${accountMode==='signup'?'new-password':'current-password'}" minlength="12" required></label>${accountMode==='signup'?'<label>Repetir contraseña<input name="confirm" type="password" autocomplete="new-password" minlength="12" required></label><p class="tag">Mínimo 12 caracteres. Confirmá tu correo cuando recibas el enlace.</p>':''}`}<div class="actions"><button class="primary">${accountMode==='signup'?'Crear cuenta':accountMode==='recover'?'Enviar enlace de recuperación':'Iniciar sesión'}</button></div></form><p id="account-error" class="error" role="alert">${esc(accountMessage)}</p><div class="toolbar"><button data-account="mode-login">Ya tengo cuenta</button><button data-account="mode-signup">Crear cuenta</button><button class="subtle" data-account="mode-recover">Olvidé mi contraseña</button></div><p class="tag">Al entrar, la sesión queda guardada en este dispositivo. Usá Cerrar sesión si lo compartís. Tus datos anteriores no se importan automáticamente.</p></section>`};
const bindBeforeAccounts=bindExtra;
bindExtra=function(){if(page!=='account'){bindBeforeAccounts();return}const form=$('#personal-login');if(form)form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;$('#account-error').textContent='Conectando…';try{await ensureAccount();const f=new FormData(form),email=String(f.get('email')).trim();let result;if(accountMode==='recover'){result=await accountClient.auth.resetPasswordForEmail(email,{redirectTo:accountReturn()});if(result.error)throw result.error;accountMessage='Si el correo tiene una cuenta, recibirás un enlace para recuperar el acceso.';render();return}const password=String(f.get('password'));if(accountMode==='signup'){if(password!==f.get('confirm'))throw Error('Las contraseñas no coinciden.');result=await accountClient.auth.signUp({email,password,options:{emailRedirectTo:accountReturn()}})}else result=await accountClient.auth.signInWithPassword({email,password});if(result.error)throw result.error;accountMessage=accountMode==='signup'&&!result.data.session?'Revisá tu correo para confirmar la cuenta. Después podés iniciar sesión.':'';if(!result.data.session)render()}catch(error){if($('#account-error'))$('#account-error').textContent=authMessage(error);button.disabled=false}};const recovery=$('#password-recovery');if(recovery)recovery.onsubmit=async event=>{event.preventDefault();const f=new FormData(recovery);if(f.get('password')!==f.get('confirm')){$('#account-error').textContent='Las contraseñas no coinciden.';return}const button=recovery.querySelector('button');button.disabled=true;const {error}=await accountClient.auth.updateUser({password:f.get('password')});if(error){$('#account-error').textContent=authMessage(error);button.disabled=false;return}recoveringPassword=false;accountMessage='Contraseña actualizada.';render()}};
function authMessage(error){const text=String(error?.message||'');if(/invalid login|invalid_credentials/i.test(text))return 'Correo o contraseña incorrectos.';if(/email.*confirm/i.test(text))return 'Primero confirmá tu correo con el enlace recibido.';if(/rate|limit|too many/i.test(text))return 'Llegaste al límite de intentos. Esperá unos minutos y volvé a probar.';if(/coinciden/.test(text))return text;if(/password|weak/i.test(text))return 'Elegí una contraseña de al menos 12 caracteres.';if(/network|fetch|timeout/i.test(text))return 'No pudimos conectar. Revisá tu conexión.';return 'No se pudo completar el acceso. Revisá tus datos y volvé a intentar.'}
document.addEventListener('click',async event=>{const action=event.target.closest('[data-account]')?.dataset.account;if(!action)return;try{if(action.startsWith('mode-')){accountMode=action.slice(5);accountMessage='';render();return}if(action==='backup'){backup();return}if(action==='sync'){await push();notify('Tus datos están guardados.');return}if(action==='reload'){if(dirty||accountDoc.conflict)throw Error('Tenés cambios pendientes. Guardalos o resolvé el conflicto antes de cargar otra copia.');await pull(false);return}if(action==='resolve'){if(!confirm('Se descargará tu copia pendiente y después se cargará la versión de tu cuenta. ¿Continuar?'))return;backup();state=await accountDoc.load(true);dirty=false;cloudReady=true;render();return}if(action==='migrate'){if(!cloudReady)throw Error('Esperá a que termine de cargar tu cuenta');if(!confirm('¿Reemplazar esta cuenta por los datos guardados sin sesión en este dispositivo? Descargá antes un respaldo si ya tenés datos en la cuenta.'))return;undo=JSON.parse(JSON.stringify(state));state=deviceState();commit('Datos importados. Se guardarán en tu cuenta.');return}if(action==='logout'){if(dirty){try{await push()}catch{throw Error('Tenés cambios sin guardar. Descargá un respaldo y resolvé el guardado antes de cerrar sesión.')}}const owner=accountDoc?.owner;const {error}=await accountClient.auth.signOut({scope:'local'});if(error)throw error;if(owner)localStorage.removeItem('kapi.account.'+owner);accountMessage='';await activateAccount(null)}}catch(error){accountMessage=String(error.message||'No se pudo completar la acción.');notify(accountMessage);accountPaint()}});
const renderBeforeAccounts=render;
render=function(){renderBeforeAccounts();if(session){let sync=$('#account-sync-status');if(!sync){sync=document.createElement('button');sync.id='account-sync-status';sync.className='subtle sync-status';sync.dataset.page='account';sync.textContent=accountStatus();$('#app').prepend(sync)}}else if(page==='home'&&accountEnabled){const card=document.createElement('div');card.className='account-banner';card.innerHTML='<span>Guardá tus gastos con tu cuenta personal.</span><button data-page="account">Entrar / Crear cuenta</button>';$('#app').prepend(card)}};
let accountPromise=null;function ensureAccount(){if(!accountEnabled)return Promise.reject(Error('La cuenta no está configurada'));return accountPromise||(accountPromise=initializeAccount().catch(e=>{accountPromise=null;throw e}))}
async function initializeAccount(){await loadKapiScript('vendor/supabase.js');accountClient=window.supabase.createClient(accountSettings.url,accountSettings.publicKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce',storageKey:'kapi.auth.v1'}});accountDoc=new CloudDocument({client:accountClient,storage:localStorage,validate:Finance.migrate,initial:()=>Finance.migrate(initial()),onChange:()=>{dirty=accountDoc.pending;accountPaint()}});accountClient.auth.onAuthStateChange((event,next)=>{if(event==='PASSWORD_RECOVERY'){recoveringPassword=true;page='account'}setTimeout(()=>activateAccount(next).catch(()=>notify('No se pudo cargar la cuenta.')),0)});return accountClient.auth.getSession().then(({data,error})=>{if(error){accountMessage='Volvé a iniciar sesión.';render();return}return activateAccount(data.session)}).catch(()=>notify('No se pudo restaurar la sesión.'))}
if(accountEnabled&&(localStorage.getItem('kapi.auth.v1')||new URLSearchParams(location.search).has('code')||location.hash.includes('access_token')))queueMicrotask(()=>ensureAccount().catch(()=>{}));
window.addEventListener('online',()=>queueAccountSave());
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&cloudReady){if(dirty)queueAccountSave();else pull(false).catch(()=>{})}});
render();


// planning.js
'use strict';
function goalsScreen(){const now=Core.date(new Date());return intro('Tus metas de ahorro.','Un monto, una fecha y pasos que podés seguir.')+`<div class="sectionhead"><button class="primary" data-plan="new-goal">+ Crear meta</button></div><div class="budgets">${state.goals.map(g=>{const p=KapiPlanning.goalProgress(g,now);return `<article class="card"><div class="row"><h3>🎯 ${esc(g.name)}</h3><button class="subtle" data-plan="edit-goal" data-id="${esc(g.id)}">Editar</button></div><p class="muted">Objetivo: ${fmt(g.target,g.currency)} · ${esc(short(g.due))} ${g.due.slice(0,4)}</p><div class="amount">${fmt(p.saved,g.currency)} ahorrados</div><div class="meter" role="meter" aria-label="Avance de ${esc(g.name)}" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p.percent}%"></i></div><p>${p.percent}% · Faltan ${fmt(p.remaining,g.currency)}</p><p class="notice">${p.remaining===0?'¡Meta cumplida!':p.overdue?'La fecha pasó. Podés ajustar tu meta.':'Referencia: '+fmt(p.monthly,g.currency)+' por mes durante '+p.months+' mes(es).'}</p><div class="toolbar"><button data-plan="contribute" data-id="${esc(g.id)}">+ Registrar aporte</button><button class="subtle danger" data-plan="delete-goal" data-id="${esc(g.id)}">Eliminar meta</button></div><details><summary class="muted">Ver aportes (${g.contributions.length})</summary>${g.contributions.map(c=>`<div class="row"><span>${esc(c.date)} · ${fmt(c.amount,g.currency)}</span><button class="subtle danger" data-plan="delete-contribution" data-id="${esc(g.id)}" data-contribution="${esc(c.id)}">Quitar</button></div>`).join('')}</details></article>`}).join('')||'<div class="empty card">Ejemplo: ahorrar Bs 2.000 en 3 meses. Creá tu primera meta para calcular el aporte mensual.</div>'}</div><p class="tag">Los aportes registran tu avance: no transfieren dinero ni se registran como gastos automáticamente.</p>`}
function goalModal(id){const g=state.goals.find(x=>x.id===id),now=Core.date(new Date());openModal(g?'Editar meta':'Crear meta de ahorro','Ejemplo: Bs 2.000 en tres meses. Podés registrar aportes cuando ahorres.',`<div class="fields"><label class="wide">Nombre de la meta<input name="name" maxlength="70" required value="${esc(g?.name||'')}" placeholder="Ej. Fondo de emergencia"></label><label>Cuánto querés ahorrar<input name="target" type="number" min="0.01" max="1000000000000" step="0.01" required value="${g?.target||''}"></label><label>Moneda<select name="currency" ${g?.contributions.length?'disabled':''}>${currencyOptions(g?.currency||state.display)}</select></label><label>Plazo rápido (meses)<input id="goal-months" type="number" min="1" max="120" step="1" value="3"></label><label>Fecha objetivo<input name="due" type="date" required min="${g?.created||now}" value="${g?.due||KapiPlanning.addMonths(now,3)}"></label></div>`,'Guardar meta',f=>{const due=f.get('due');if(!Core.validDate(due)||due<(g?.created||now))throw Error('La fecha objetivo no es válida.');const data={id:g?.id||uid(),name:textValue(f,'name',70),target:numberValue(f,'target'),currency:g?.contributions.length?g.currency:f.get('currency'),created:g?.created||now,due,contributions:g?.contributions||[]};if(g)Object.assign(g,data);else state.goals.push(data);$('#modal').close();commit('Meta guardada.')});$('#goal-months').oninput=e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=120)$('#modal input[name="due"]').value=KapiPlanning.addMonths(now,n)}}
function contributionModal(id){const g=state.goals.find(x=>x.id===id);if(!g)return;const now=Core.date(new Date());openModal('Registrar aporte',esc(g.name)+' · '+g.currency,`<div class="fields"><label>Monto ahorrado<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" required></label><label>Fecha<input name="date" type="date" max="${now}" value="${now}" required></label></div>`,'Guardar aporte',f=>{const date=f.get('date');if(!Core.validDate(date)||date>now)throw Error('Fecha inválida');g.contributions.push({id:uid(),amount:numberValue(f,'amount'),date});$('#modal').close();commit('Aporte guardado. No se movió dinero desde ninguna cuenta.')})}
const frequencyLabel=r=>({weekly:'Cada semana',fortnightly:'Cada 2 semanas',twice:'Dos veces al mes',monthly:'Cada mes'}[r.frequency]);
function rulesCard(){return `<section class="card"><div class="row"><h2>Cobros programados</h2><button class="primary" data-plan="new-rule">+ Programar cobro</button></div><p class="muted">Ej.: USD 200 cada dos semanas o Bs 4.000 al mes.</p>${state.incomeRules.map(r=>`<article class="rule-row"><div><h3>${esc(r.name)} · ${fmt(r.amount,r.currency)}</h3><small class="muted">${frequencyLabel(r)} · desde ${esc(r.anchor)} · ${r.auto?'Registro automático activado':'Solo previsión'}</small></div><div class="toolbar"><button data-plan="edit-rule" data-id="${esc(r.id)}">Editar</button><button class="danger" data-plan="delete-rule" data-id="${esc(r.id)}">Eliminar</button></div></article>`).join('')||'<p class="empty">Todavía no programaste cobros.</p>'}<p class="tag">La automatización se procesa al abrir o volver a KAPI. No verifica depósitos bancarios ni funciona como un pago o transferencia. Al eliminar una regla se conservan sus ingresos registrados.</p></section>`}
function ruleModal(id){const r=state.incomeRules.find(x=>x.id===id),now=Core.date(new Date());openModal(r?'Editar cobro':'Programar un cobro','Elegí el primer cobro que KAPI debe tener en cuenta. No dupliques uno que ya registraste.',`<div class="fields"><label class="wide">Nombre<input name="name" maxlength="70" required value="${esc(r?.name||'Sueldo')}"></label><label>Monto por cobro<input name="amount" type="number" min="0.01" max="1000000000000" step="0.01" required value="${r?.amount||''}"></label><label>Moneda<select name="currency">${currencyOptions(r?.currency||state.display)}</select></label><label>Frecuencia<select name="frequency">${[['weekly','Cada semana'],['fortnightly','Cada dos semanas · 14 días'],['monthly','Cada mes'],['twice','Dos veces al mes']].map(([v,t])=>`<option value="${v}" ${r?.frequency===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Primer cobro a considerar<input name="anchor" type="date" required min="${r?r.anchor:now}" value="${r?.anchor||now}"></label><label class="rule-twice">Primer día del mes<input name="day1" type="number" min="1" max="28" step="1" value="${r?.day1||1}"></label><label class="rule-twice">Segundo día del mes<input name="day2" type="number" min="2" max="31" step="1" value="${r?.day2||15}"></label><label class="wide checkbox-label"><input name="auto" type="checkbox" ${r?.auto?'checked':''}> Registrar este ingreso automáticamente al llegar su fecha y abrir KAPI</label></div><p class="tag">Los registros automáticos se identifican como programados. Los USD usan el cambio configurado cuando KAPI los procesa; podés editar el cambio de cada movimiento.</p>`,'Guardar cobro',f=>{const anchor=f.get('anchor'),day1=Number(f.get('day1')),day2=Number(f.get('day2'));if(!Core.validDate(anchor)||(!r&&anchor<now))throw Error('Elegí una fecha de inicio desde hoy.');const data={id:r?.id||uid(),name:textValue(f,'name',70),amount:numberValue(f,'amount'),currency:f.get('currency'),frequency:f.get('frequency'),anchor,day1,day2,auto:f.get('auto')==='on'};const candidate={...state,incomeRules:r?state.incomeRules.map(x=>x.id===r.id?data:x):[...state.incomeRules,data]};KapiPlanning.validate(candidate);if(r)Object.assign(r,data);else state.incomeRules.push(data);$('#modal').close();commit('Cobro programado.');processIncomeRules()});const select=$('#modal select[name="frequency"]');const toggle=()=>document.querySelectorAll('#modal .rule-twice').forEach(e=>{e.hidden=select.value!=='twice'});select.onchange=toggle;toggle()}
let processingRules=false;
function processIncomeRules(){if(processingRules||accountLoading||(session&&!cloudReady))return;processingRules=true;try{const pending=KapiPlanning.dueReceipts(state,Core.date(new Date()));if(pending.length){state.receipts.push(...pending);commit(pending.length+' ingreso(s) programado(s) registrados. Revisalos en Movimientos.')}}catch(error){notify(error.message)}finally{processingRules=false}}
const budgetScreenBeforeGoals=friendlyBudgets;
friendlyBudgets=function(){return '<div class="segment"><button data-plan="budgets" class="selected">Presupuestos</button><button data-plan="goals">Metas de ahorro</button></div>'+budgetScreenBeforeGoals()};
const renderBeforePlanning=render;
render=function(){if(page==='goals'){const savedPage=page;page='budgets';renderBeforePlanning();page=savedPage;$('#app').innerHTML='<div class="segment"><button data-plan="budgets">Presupuestos</button><button data-plan="goals" class="selected">Metas de ahorro</button></div>'+goalsScreen()}else{renderBeforePlanning();if(page==='income-settings'){const box=document.createElement('div');box.innerHTML=rulesCard();$('#app .settings').prepend(box);if(state.incomeRules.length){$('#income-form').hidden=true;const note=document.createElement('p');note.className='notice';note.textContent='La previsión principal usa tus cobros programados; no se vuelve a sumar el sueldo de la configuración anterior.';$('#app .settings').append(note)}}}if(page==='home'){const next=KapiPlanning.upcoming(state,Core.date(new Date()));if(next){const last=$('#app .mini-stats > div:last-child');if(last)last.innerHTML='<small>Próximo cobro previsto</small><strong>'+short(next.date)+'</strong><span class="muted">'+fmt(next.amount,next.currency)+'</span>'}}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-plan]');if(!el)return;const id=el.dataset.id;switch(el.dataset.plan){case'goals':go('goals');break;case'budgets':go('budgets');break;case'new-goal':goalModal();break;case'edit-goal':goalModal(id);break;case'contribute':contributionModal(id);break;case'delete-goal':if(confirm('¿Eliminar esta meta y su registro de aportes? No afecta tus gastos ni tus ingresos.')){undo=JSON.parse(JSON.stringify(state));state.goals=state.goals.filter(g=>g.id!==id);persist();render();notify('Meta eliminada.',true)}break;case'delete-contribution':{const g=state.goals.find(x=>x.id===id);if(g&&confirm('¿Quitar este aporte de la meta?')){undo=JSON.parse(JSON.stringify(state));g.contributions=g.contributions.filter(c=>c.id!==el.dataset.contribution);persist();render();notify('Aporte quitado.',true)}break}case'new-rule':ruleModal();break;case'edit-rule':ruleModal(id);break;case'delete-rule':if(confirm('¿Eliminar la programación? Los ingresos ya registrados se conservarán.')){undo=JSON.parse(JSON.stringify(state));state.incomeRules=state.incomeRules.filter(r=>r.id!==id);persist();render();notify('Programación eliminada.',true)}break;case'delete-budget':confirmDelete('budget',id);break}});
const activateBeforePlanning=activateAccount;
activateAccount=async function(next){await activateBeforePlanning(next);processIncomeRules()};
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')processIncomeRules()});
setInterval(processIncomeRules,60*60*1000);
processIncomeRules();render();


// budget-details.js
'use strict';
function budgetDetails(id){const b=state.budgets.find(x=>x.id===id);if(!b)return;const rows=state.expenses.filter(e=>e.budget===id&&e.date.slice(0,7)===selectedMonth).sort((a,b)=>b.date.localeCompare(a.date));const spent=Core.sum(rows,e=>Core.bs(e.amount,e.currency,e.rate)),limit=Core.bs(b.amount,b.currency,state.rate);openModal('Gastos de '+esc(b.name),esc(titleMonth(selectedMonth))+' · '+rows.length+' movimiento(s)',`<div class="notice"><strong>${money(spent)} gastados</strong><p>Presupuesto: ${fmt(b.amount,b.currency)} · ${spent>limit?'Exceso: '+money(spent-limit):'Disponible: '+money(limit-spent)}</p></div><div class="budget-detail-list">${rows.map(e=>`<article class="budget-detail-row"><div><strong>${esc(e.name)}</strong><p class="tag">${esc(short(e.date))} ${e.date.slice(0,4)}</p></div><div><strong>${fmt(e.amount,e.currency)}</strong>${e.currency!==state.display?'<p class="tag">'+money(Core.bs(e.amount,e.currency,e.rate))+' equivalente</p>':''}<button type="button" class="subtle" data-detail-edit="${esc(e.id)}" aria-label="Editar gasto ${esc(e.name)}">Editar</button></div></article>`).join('')||'<p class="empty">Todavía no hay gastos en este presupuesto durante el mes seleccionado.</p>'}</div><button type="button" data-detail-add="${esc(id)}">+ Registrar gasto en este presupuesto</button><p class="tag">Los totales usan el cambio guardado en cada movimiento. Cambiá el mes del informe para revisar otro período.</p>`,'Cerrar',()=>$('#modal').close());$('#modal-form .cancel').remove()}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-budget-details]');if(detail){budgetDetails(detail.dataset.budgetDetails);return}const card=e.target.closest('.budget-card[data-budget-id]');if(card&&!e.target.closest('button,a,input,select,textarea')){budgetDetails(card.dataset.budgetId);return}const edit=e.target.closest('[data-detail-edit]');if(edit){$('#modal').close();expenseModal(edit.dataset.detailEdit);return}const add=e.target.closest('[data-detail-add]');if(add){$('#modal').close();expenseModal();const field=$('#expense-budget');field.value=add.dataset.detailAdd;field.dispatchEvent(new Event('change',{bubbles:true}))}});


// runtime.js
'use strict';
const kapiScripts=new Map();
function loadKapiScript(path){if(kapiScripts.has(path))return kapiScripts.get(path);const p=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL(path+'?v='+window.KAPI_RELEASE,location.href);s.onload=resolve;s.onerror=()=>{kapiScripts.delete(path);s.remove();reject(Error('No se pudo cargar esta herramienta. Revisá la conexión.'))};document.head.append(s)});kapiScripts.set(path,p);return p}
let chatLoading=null;
function loadChat(){return chatLoading||(chatLoading=(async()=>{await loadKapiScript('assistant-core.js');await loadKapiScript('voice.js');await loadKapiScript('assistant.js')})().catch(e=>{chatLoading=null;throw e}))}
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',budgets:'M12 3a9 9 0 1 0 9 9h-9zm3 0v6h6',expenses:'M5 17 19 3M8 3h11v11M5 7v14h14',assistant:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',theme:'M20 13A8 8 0 0 1 11 4a8 8 0 1 0 9 9',tools:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2'};
const svgIcon=name=>'<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[name]+'"/></svg>';
for(const b of document.querySelectorAll('nav button'))b.innerHTML=svgIcon(b.dataset.page)+'<span>'+esc(b.textContent.trim().replace(/^[◫◉↗✳]\s*/,''))+'</span>';
const toolsButton=document.querySelector('.toptools [data-page="tools"]');toolsButton.innerHTML=svgIcon('tools')+'<span>Ajustes</span>';
function syncTheme(){const dark=state.theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.body.classList.toggle('dark',dark);$('#theme').setAttribute('aria-pressed',String(dark));$('#theme').innerHTML=svgIcon('theme');for(const m of document.querySelectorAll('meta[name="theme-color"]'))m.content=dark?'#141b18':'#f4f3ef'}
function dataLabels(){for(const table of document.querySelectorAll('.tablewrap table')){const headings=[...table.querySelectorAll('thead th')].map(e=>e.textContent);for(const row of table.querySelectorAll('tbody tr'))[...row.children].forEach((td,i)=>td.dataset.label=headings[i]||'Acciones')}}
function aiSettings(){const id=session?.user.id||'guest',enabled=localStorage.getItem('kapi.ai.consent.'+id)==='yes';return `<section class="card"><h2>Asistente y privacidad</h2><p>${enabled?'IA autorizada para esta cuenta.':'IA desactivada. El modo local funciona sin enviar tus cifras.'} ${accountSettings.aiReady?'Proveedor: '+esc(accountSettings.aiProvider||'IA configurada')+'.':'La conexión del proveedor todavía está pendiente.'}</p><div class="toolbar"><button data-runtime="${enabled?'ai-off':'ai-on'}">${enabled?'Desactivar IA':'Activar IA con consentimiento'}</button><button data-runtime="clear-chat">Borrar conversación</button></div><label class="checkbox-label"><input id="read-answers" type="checkbox" ${localStorage.getItem('kapi.voice.read')==='yes'?'checked':''}>Leer respuestas en voz alta</label><p class="tag">El chat vive en memoria: se elimina al recargar, cambiar de cuenta o borrar la conversación. KAPI no guarda audio.</p></section><section class="card"><h2>Protegé tus registros</h2><p>Borrar los datos del sitio elimina los registros locales y la sesión. Usá un respaldo o comprobá que tu cuenta indique «Guardado en tu cuenta».</p><button data-runtime="persist">Proteger almacenamiento de este dispositivo</button><p class="tag" id="storage-status">El navegador decide cuánto tiempo conserva los datos; esta opción no sustituye un respaldo.</p></section>`}
assistantPage=()=>window.KapiChat?KapiChat.screen():intro('Tu asistente KAPI.','Preparando las herramientas…')+'<p role="status">Cargando el asistente. Si no hay conexión, intentá nuevamente al conectarte.</p><button data-runtime="retry-chat">Reintentar</button>';
const finalRenderBefore=render;
render=function(){finalRenderBefore();document.querySelectorAll('[data-release]').forEach(e=>e.textContent=window.KAPI_RELEASE);syncTheme();dataLabels();document.body.classList.toggle('chat-open',page==='assistant');document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.page===(page==='goals'?'budgets':page);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const foot=document.querySelector('.asidefoot p');if(foot)foot.textContent=session?accountStatus():'Guardado solo en este dispositivo';if(page==='tools'){$('#app .settings').insertAdjacentHTML('beforeend',aiSettings());$('#read-answers').onchange=e=>localStorage.setItem('kapi.voice.read',e.target.checked?'yes':'no')}if(page==='account'&&accountEnabled&&!accountClient)ensureAccount().catch(e=>notify(e.message));if(page==='assistant'){if(window.KapiChat)KapiChat.mount();else loadChat().then(()=>{if(page==='assistant')render()}).catch(()=>notify('No se pudo cargar el asistente. Revisá la conexión.'))}else{window.KapiVoice?.stop();window.speechSynthesis?.cancel()}};
let modalOpener=null;const oldModal=openModal;openModal=function(...args){modalOpener=document.activeElement;oldModal(...args);requestAnimationFrame(()=>$('#modal input:not([type="hidden"]),#modal textarea,#modal button')?.focus())};$('#modal').addEventListener('close',()=>{window.KapiVoice?.stop();if(modalOpener?.isConnected)modalOpener.focus()});
const oldChooser=movementChooser;movementChooser=function(){oldChooser();const target=document.createElement('section');target.className='notice';target.innerHTML='<label>O dictá un movimiento<input id="movement-dictation" maxlength="2000" placeholder="Gasté 45 Bs en taxi ayer"></label><div class="toolbar"><button type="button" data-voice-target="movement-dictation" aria-label="Dictar movimiento" aria-pressed="false">Dictar</button><button type="button" data-runtime="review-dictation">Revisar en el asistente</button></div><p id="movement-voice-status" role="status"></p>';$('#modal-form').append(target);loadChat().then(()=>KapiVoice.mount()).catch(()=>{})};
document.addEventListener('click',async e=>{const action=e.target.closest('[data-runtime]')?.dataset.runtime;if(!action)return;try{if(action==='ai-on'){if(!session){notify('Iniciá sesión para habilitar la IA.');go('account');return}openModal('Activar IA en tu cuenta','Es opcional. Podés seguir usando el modo local.',`<p>Al consultar, se enviarán tu mensaje y un resumen mínimo del mes al proveedor ${esc(accountSettings.aiProvider||'configurado en KAPI')}. No se enviará el documento completo, contraseñas ni números de cuenta. Las consultas pueden incluir importes y categorías.</p><p>Groq declara que no usa entradas y salidas para entrenamiento sin permiso; puede conservar datos por seguridad o fallos hasta 30 días salvo retención cero activada. La conexión tiene cupo y puede volver a modo local. KAPI no almacena el chat en servidor.</p><p>Mientras el proveedor no esté configurado, seguirá funcionando el modo local.</p>`,'Aceptar y activar',()=>{localStorage.setItem('kapi.ai.consent.'+session.user.id,'yes');$('#modal').close();render()});return}if(action==='ai-off'){localStorage.removeItem('kapi.ai.consent.'+(session?.user.id||'guest'));window.KapiChat?.reset();render()}if(action==='clear-chat'){window.KapiChat?.reset();notify('Conversación borrada.')}if(action==='persist'){const granted=await navigator.storage?.persist?.();$('#storage-status').textContent=granted?'El navegador concedió almacenamiento persistente. Seguí guardando respaldos.':'El navegador no concedió persistencia. Conservá respaldos o sincronizá tu cuenta.'}if(action==='retry-chat'){await loadChat();render()}if(action==='review-dictation'){const text=$('#movement-dictation').value;$('#modal').close();await loadChat();go('assistant');$('#chat-text').value=text;$('#chat-text').focus()}}catch(error){notify(error.message||'No se pudo completar la acción.')}});
function checkDay(){const now=Core.date(new Date());if(now!==today){const oldMonth=today.slice(0,7);today=now;if(selectedMonth===oldMonth)selectedMonth=today.slice(0,7);processIncomeRules();render()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkDay()});setInterval(checkDay,60000);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{if(!localStorage.getItem('kapi.theme')){state.theme=e.matches?'dark':'light';render()}});
function keyboardViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--keyboard-height',Math.max(0,innerHeight-(v?.height||innerHeight)-(v?.offsetTop||0))+'px')}
window.visualViewport?.addEventListener('resize',keyboardViewport);keyboardViewport();render();

